-- ContrataCR Pro, database part 19 of 21 (PRO_ENABLED stays false: nothing here turns Pro on).
-- Generated by scripts/pro/build-pro-migrations.mjs from the ordered local SQL manifest (scripts/pro/local-sql-manifest.mjs);
-- do not edit by hand: change docs/pro/sql and regenerate. Every module is idempotent (create if not exists / or replace /
-- guarded blocks) and keeps its own RLS, grants (service_role only unless stated) and pinned search_path.
-- Modules, in order:
--   directory-listings-local.sql sha256:2a0823f79542
--   dir-listing-photos-bucket-local.sql sha256:39973593c18f
--   pro-editions-local.sql sha256:59bfab14f6c3
--   pro-editions-team-gate-local.sql sha256:7ad8f67e9c0d
--   pro-work-activity-local.sql sha256:22c199e668de
--   payables-cashflow-local.sql sha256:fbe862e982b8
-- ===== directory-listings-local.sql =====
-- LOCAL PRO ONLY. Multivertical round V1 (+ data part of R1), 2026-11-16: classified listings (anuncios) for
-- vehicles (/vehiculos) and real estate (/inmuebles).
-- Depends on: directory-core-local.sql (dir_places, dir_immutable, dir_derived_uuid, dir_reports),
--             directory-claims-local.sql (dir_place_managers: who manages a dealer/agency place) and
--             vehicles-catalog-local.sql (ref_vehicle_makes, ref_vehicle_models).
-- Optional at run time: team-roles-local.sql (pro_role_of / pro_company_members) for the R2 agent assignment;
--             without it assigning an agent answers 55000 dir_listing_team_unavailable (unassigning still works).
-- UI-gap round (2026-11-16, after V1):
-- * Public readers include 'reserved' (with the status column) so the page shows the «Reservado» badge.
-- * dir_listing_owner_list(actor, vertical, filter active|closed, cursor): Pro inventory reader; private fields
--   (plate, VIN, plano, folio, exact coordinates) only for the seller of each listing, never for co-managers.
-- * Linking place_id requires the seller to be an active manager of that place (dir_place_managers).
-- * R2 agent: dir_listings.agent_profile_id (properties only) + dir_listing_assign_agent (owner/manager of the
--   linked place; the agent must be an admin/manager/member of the place owner's Pro team, pro_role_of).
-- * Declared financing PER PLACE (dir_listing_financing): one dealer program for the whole lot, shown on vehicle
--   listings that opted in (seller_financing) only while the declaration is younger than financing_max_age_days,
--   always flagged declaredBySeller.
-- * V3 photos (dir_listing_media): ≤30 per listing, sha256, size, 1600/800/320 variants, exif_stripped must be
--   true, uploaded_by. Publishing (and staying public) needs min_photos_publish (4). Anti-fraud flags
--   (dir_listing_flags, append-only) move moderation to 'review': same photo used by another seller, price below
--   price_outlier_pct (50 %) of the median for the same model+year with ≥ price_outlier_min_samples (5) samples,
--   and reports_to_review (3) distinct abuse reporters. Public reports reuse dir_reports (listing_id column).
-- * dir_listings: generic listing (public_code of 6 chars, vertical vehiculos|inmuebles, seller_kind business|private,
--   optional dealer/agency place, status machine, CRC|USD price + price_crc_norm via dir_fx_rates, 60-day expiry
--   renewable by function (no cron: readers filter expires_at, dir_listing_expire_due marks them on demand), CAS
--   revision (40001), moderation_status, multi-country fields).
-- * dir_listing_vehicle / dir_listing_property: per-vertical extensions. plate_private, vin_private,
--   cadastral_plan_private and folio_real_private are NEVER returned by a public reader.
-- * Public readers: views public_vehicle_listings / public_property_listings (security_invoker) and
--   dir_listing_public(code). Only published, unexpired, moderation clear/approved; coordinates are always
--   fuzzed 305–495 m deterministically per listing (same offset every time, so repeated reads cannot be averaged).
-- * Limits (dir_listing_limits, configurable): private sellers ≤2 active (draft/published/reserved) per vertical;
--   business sellers without business_verified ≤5 published (published/reserved). 54000 + hint.
-- * Receipts (dir_listing_actions) and history (dir_listing_history) are immutable. Order NEVER depends on
--   payment: there is no paid/featured/sponsored column; renewing does not change published_at.
-- Tables: RLS on, service_role only, no DELETE grant, TRUNCATE blocked. Functions security invoker, pinned
-- search_path, executable only by service_role.
begin;

-- ---------------------------------------------------------------- tables
create table if not exists public.dir_fx_rates(
 rate_date date primary key,
 usd_crc numeric(12,4) not null check(usd_crc>0 and usd_crc<100000),
 source text not null check(source in('bccr','manual')),
 recorded_by uuid,recorded_at timestamptz not null default clock_timestamp()
);

create table if not exists public.dir_listing_limits(
 key text primary key check(key in('private_active_per_vertical','business_unverified_published','min_photos_publish','price_outlier_min_samples',
  'price_outlier_pct','financing_max_age_days','reports_to_review')),
 value integer not null check(value between 0 and 10000),
 updated_at timestamptz not null default clock_timestamp(),
 check(key<>'min_photos_publish' or value between 1 and 30),
 check(key<>'price_outlier_pct' or value between 1 and 99),
 check(key not in('price_outlier_min_samples','reports_to_review','financing_max_age_days') or value>=1)
);
insert into public.dir_listing_limits(key,value) values('private_active_per_vertical',2),('business_unverified_published',5),('min_photos_publish',4),
 ('price_outlier_min_samples',5),('price_outlier_pct',50),('financing_max_age_days',180),('reports_to_review',3) on conflict(key) do nothing;

-- Seller registry (one row per profile that has listed). business_verified is set only by staff
-- (cédula jurídica + Hacienda + personería; V2 adds the evidence tables).
create table if not exists public.dir_listing_sellers(
 profile_id uuid primary key,
 business_verified boolean not null default false,
 verified_by uuid,verified_at timestamptz,note text check(length(note)<=500),
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
 check(not business_verified or (verified_by is not null and verified_at is not null))
);

create table if not exists public.dir_listings(
 id uuid primary key,
 public_code text not null unique check(public_code~'^[2-9a-hjkmnp-z]{6}$'),
 vertical text not null check(vertical in('vehiculos','inmuebles')),
 seller_kind text not null check(seller_kind in('business','private')),
 seller_profile_id uuid not null references public.dir_listing_sellers(profile_id),
 place_id uuid references public.dir_places(id),
 status text not null default 'draft' check(status in('draft','published','reserved','sold','rented','archived','suspended','expired')),
 moderation_status text not null default 'clear' check(moderation_status in('clear','review','approved','rejected')),
 title text not null check(length(btrim(title)) between 5 and 120),
 description text check(length(description) between 1 and 5000),
 price_minor bigint not null check(price_minor>0 and price_minor<=100000000000000),
 currency text not null check(currency in('CRC','USD')),
 price_crc_norm bigint check(price_crc_norm>0),fx_rate_date date,fx_usd_crc numeric(12,4),
 country_code text not null default 'CR' check(country_code~'^[A-Z]{2}$'),
 admin_area_1 text check(length(admin_area_1) between 1 and 80),
 admin_area_2 text check(length(admin_area_2) between 1 and 80),
 admin_area_3 text check(length(admin_area_3) between 1 and 80),
 locality text check(length(locality) between 1 and 80),
 lat numeric(9,6) check(lat between -90 and 90),lng numeric(9,6) check(lng between -180 and 180),
 published_at timestamptz,expires_at timestamptz,status_changed_at timestamptz not null default clock_timestamp(),
 revision integer not null default 1 check(revision>0),
 -- R2: team agent in charge of a property listing (profile id; validated against the Pro team at assignment).
 agent_profile_id uuid,
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
 check((lat is null)=(lng is null)),
 check(seller_kind='business' or place_id is null),
 check(agent_profile_id is null or (vertical='inmuebles' and place_id is not null)),
 check((currency='CRC' and price_crc_norm=price_minor and fx_rate_date is null) or (currency='USD' and (price_crc_norm is null)=(fx_rate_date is null) and (fx_rate_date is null)=(fx_usd_crc is null))),
 check(status not in('published','reserved','expired') or (published_at is not null and expires_at is not null))
);
create index if not exists dir_listings_public on public.dir_listings(vertical,status,country_code,expires_at);
create index if not exists dir_listings_seller on public.dir_listings(seller_profile_id,vertical,status);
create index if not exists dir_listings_price on public.dir_listings(vertical,price_crc_norm) where status='published';
create index if not exists dir_listings_place on public.dir_listings(place_id) where place_id is not null;
create index if not exists dir_listings_expiry on public.dir_listings(expires_at) where status in('published','reserved');

create table if not exists public.dir_listing_vehicle(
 listing_id uuid primary key references public.dir_listings(id),
 make_id bigint not null references public.ref_vehicle_makes(id),
 model_id bigint not null references public.ref_vehicle_models(id),
 vehicle_type text not null check(vehicle_type in('car','suv','pickup','van','truck','motorcycle','atv')),
 version text check(length(btrim(version)) between 1 and 80),
 year smallint not null check(year between 1950 and 2100),
 condition text not null check(condition in('new','used')),
 mileage_km integer check(mileage_km between 0 and 2000000),
 transmission text check(transmission in('manual','automatic','cvt','other')),
 fuel text check(fuel in('gasoline','diesel','hybrid','plugin_hybrid','electric','lpg','other')),
 drivetrain text check(drivetrain in('4x2','4x4','awd')),
 engine_cc integer check(engine_cc between 49 and 20000),
 doors smallint check(doors between 0 and 6),seats smallint check(seats between 1 and 60),
 color text check(length(btrim(color)) between 1 and 40),
 accepts_trade_in boolean not null default false,seller_financing boolean not null default false,
 -- Declared by the seller (not verified by ContrataCR); the page labels them as declarations.
 marchamo_current_declared boolean,rtv_current_declared boolean,taxes_paid_declared boolean,
 -- PRIVATE: never in a public reader (plate visibility pending legal review).
 plate_private text check(plate_private~'^[A-Z0-9][A-Z0-9 -]{0,10}[A-Z0-9]$'),
 vin_private text check(vin_private~'^[A-HJ-NPR-Z0-9]{11,17}$')
);
create index if not exists dir_listing_vehicle_model on public.dir_listing_vehicle(make_id,model_id,year);

create table if not exists public.dir_listing_property(
 listing_id uuid primary key references public.dir_listings(id),
 operation text not null check(operation in('sale','rent')),
 property_type text not null check(property_type in('house','apartment','condo','lot','office','commercial','warehouse','farm','room')),
 bedrooms smallint check(bedrooms between 0 and 50),bathrooms numeric(3,1) check(bathrooms between 0 and 50),
 parking_spaces smallint check(parking_spaces between 0 and 50),
 built_m2 numeric(10,2) check(built_m2>0 and built_m2<=1000000),lot_m2 numeric(14,2) check(lot_m2>0 and lot_m2<=100000000000),
 floors smallint check(floors between 1 and 200),year_built smallint check(year_built between 1800 and 2100),
 furnished boolean,pets_allowed boolean,in_condominium boolean,
 hoa_fee_minor bigint check(hoa_fee_minor>=0 and hoa_fee_minor<=100000000000),
 min_lease_months smallint check(min_lease_months between 1 and 120),
 amenities text[] not null default '{}' check(cardinality(amenities)<=20 and amenities<@array['pool','gym','security','elevator','garden','terrace','bbq','playground','laundry','storage','air_conditioning','water_tank','solar','generator','ocean_view','mountain_view','gated','accessible']::text[]),
 -- PRIVATE: never in a public reader.
 cadastral_plan_private text check(cadastral_plan_private~'^[0-9A-Z][0-9A-Z-]{4,23}[0-9A-Z]$'),
 folio_real_private text check(folio_real_private~'^[0-9A-Z][0-9A-Z-]{4,23}[0-9A-Z]$'),
 check(operation='rent' or min_lease_months is null)
);
create index if not exists dir_listing_property_type on public.dir_listing_property(operation,property_type);

create table if not exists public.dir_listing_actions(
 actor_id uuid not null,action_id uuid not null,input jsonb not null,result jsonb not null,
 created_at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id)
);
create table if not exists public.dir_listing_history(
 id bigint generated always as identity primary key,
 listing_id uuid not null references public.dir_listings(id),
 action_id uuid not null,actor_id uuid not null,
 action text not null check(action in('create','update','status','renew','expire','suspend','reinstate','moderation','assign_agent','flag')),
 revision integer not null,before jsonb,after jsonb not null,at timestamptz not null default clock_timestamp()
);
create index if not exists dir_listing_history_listing on public.dir_listing_history(listing_id,id);
create index if not exists dir_listings_agent on public.dir_listings(agent_profile_id) where agent_profile_id is not null;

-- V3 photos. Files live in storage at dir-listings/<media id>/<1600|800|320>.<webp|jpg|avif> (the media id, never the
-- listing id, so public paths do not reveal internal ids). The upload route re-encodes, strips EXIF/GPS and
-- computes sha256 of the decoded original; exif_stripped=false is refused by the database. Rows are never
-- deleted: removal sets status='removed' and sort=null (sort is compacted 0..n-1 for the active photos).
create table if not exists public.dir_listing_media(
 id uuid primary key,
 listing_id uuid not null references public.dir_listings(id),
 sort smallint check(sort between 0 and 29),
 sha256 text not null check(sha256~'^[a-f0-9]{64}$'),
 width integer not null check(width between 200 and 1600),height integer not null check(height between 200 and 1600),
 path_1600 text not null,path_800 text not null,path_320 text not null,
 exif_stripped boolean not null check(exif_stripped),
 alt_es text check(length(alt_es) between 1 and 200),alt_en text check(length(alt_en) between 1 and 200),
 uploaded_by uuid not null,
 status text not null default 'active' check(status in('active','removed')),
 removed_by uuid,removed_at timestamptz,
 created_at timestamptz not null default clock_timestamp(),
 check(greatest(width,height)>=640),
 check((status='active')=(sort is not null) and (status='active')=(removed_at is null)),
 check(path_1600~('^dir-listings/'||id::text||'/1600\.(webp|jpg|avif)$') and path_800~('^dir-listings/'||id::text||'/800\.(webp|jpg|avif)$')
   and path_320~('^dir-listings/'||id::text||'/320\.(webp|jpg|avif)$')),
 constraint dir_listing_media_sort unique(listing_id,sort) deferrable initially deferred
);
create unique index if not exists dir_listing_media_sha_once on public.dir_listing_media(listing_id,sha256) where status='active';
create index if not exists dir_listing_media_sha on public.dir_listing_media(sha256);

-- Anti-fraud flags (append-only). One row per (listing, kind, key): the same signal never re-flags after staff
-- approval; a new signal (another photo, a lower price, more reporters) does.
create table if not exists public.dir_listing_flags(
 id bigint generated always as identity primary key,
 listing_id uuid not null references public.dir_listings(id),
 kind text not null check(kind in('duplicate_photo','price_outlier','reports')),
 key text not null check(length(key) between 1 and 80),
 detail jsonb not null default '{}' check(jsonb_typeof(detail)='object' and octet_length(detail::text)<=2048),
 created_at timestamptz not null default clock_timestamp(),
 unique(listing_id,kind,key)
);

-- Declared financing, PER PLACE (dealer program for the whole lot; see the doc for the reasoning). Declared by an
-- owner/manager of the dealer place; NOT verified by ContrataCR and always shown as declared by the seller.
create table if not exists public.dir_listing_financing(
 place_id uuid primary key references public.dir_places(id),
 annual_rate_pct numeric(5,2) not null check(annual_rate_pct between 0 and 60),
 max_term_months smallint not null check(max_term_months between 1 and 120),
 min_down_payment_pct numeric(5,2) not null check(min_down_payment_pct between 0 and 90),
 status text not null default 'active' check(status in('active','withdrawn')),
 declared_by uuid not null,declared_at timestamptz not null default clock_timestamp(),
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default clock_timestamp()
);

-- Public reports about a listing reuse dir_reports (core): listing_id set, place_id null.
alter table public.dir_reports add column if not exists listing_id uuid references public.dir_listings(id);
alter table public.dir_reports alter column place_id drop not null;
do $$begin
 if not exists(select 1 from pg_constraint where conname='dir_reports_target_check' and conrelid='public.dir_reports'::regclass) then
  alter table public.dir_reports add constraint dir_reports_target_check check(num_nonnulls(place_id,listing_id)=1
   and (listing_id is null or kind in('wrong_info','duplicate','abuse','other')));
 end if;end $$;
create index if not exists dir_reports_listing on public.dir_reports(listing_id,created_at desc) where listing_id is not null;

-- ---------------------------------------------------------------- immutability
do $$declare t text;begin foreach t in array array['dir_listing_actions','dir_listing_history','dir_listing_flags'] loop
 execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
 execute format('create trigger %I before update or delete on public.%I for each row execute function public.dir_immutable()',t||'_immutable',t);
end loop;
foreach t in array array['dir_listing_actions','dir_listing_history','dir_listings','dir_listing_vehicle','dir_listing_property','dir_listing_sellers','dir_fx_rates','dir_listing_limits',
 'dir_listing_media','dir_listing_flags','dir_listing_financing'] loop
 execute format('drop trigger if exists %I on public.%I',t||'_no_truncate',t);
 execute format('create trigger %I before truncate on public.%I for each statement execute function public.dir_immutable()',t||'_no_truncate',t);
end loop;end $$;

-- ---------------------------------------------------------------- helpers
-- camelCase input → column names; unknown keys are rejected (22023).
create or replace function public.dir_listing_remap(p_value jsonb,p_map jsonb) returns jsonb
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare k text;out jsonb:='{}';
begin
 if p_value is null then return '{}';end if;
 if jsonb_typeof(p_value)<>'object' then raise exception 'Invalid listing fields' using errcode='22023';end if;
 for k in select jsonb_object_keys(p_value) loop
  if not p_map ? k then raise exception 'Unknown listing field %',k using errcode='22023';end if;
  out:=out||jsonb_build_object(p_map->>k,p_value->k);
 end loop;
 return out;
end $$;

create or replace function public.dir_listing_limit(p_key text) returns integer
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select value from public.dir_listing_limits where key=p_key),case p_key when 'private_active_per_vertical' then 2 when 'min_photos_publish' then 4
  when 'price_outlier_pct' then 50 when 'financing_max_age_days' then 180 when 'reports_to_review' then 3 else 5 end) $$;

-- Active photos of a listing.
create or replace function public.dir_listing_photo_count(p_id uuid) returns integer
language sql stable security invoker set search_path=public,pg_temp as $$
 select count(*)::integer from public.dir_listing_media where listing_id=p_id and status='active' $$;

-- Records an anti-fraud flag once per (listing, kind, key) and moves moderation to 'review' (from clear/approved;
-- 'rejected' stays). p_log=true (actions that do not bump the revision themselves: photos, public reports) bumps
-- the revision and writes a 'flag' history row. Returns true when the flag is new.
create or replace function public.dir_listing_flag(p_id uuid,p_kind text,p_key text,p_detail jsonb,p_actor uuid,p_action uuid,p_log boolean) returns boolean
language plpgsql security invoker set search_path=public,pg_temp as $$
declare n integer;before jsonb;
begin
 insert into public.dir_listing_flags(listing_id,kind,key,detail) values(p_id,p_kind,p_key,coalesce(p_detail,'{}')) on conflict(listing_id,kind,key) do nothing;
 get diagnostics n=row_count;
 if n=0 then return false;end if;
 if p_log then before:=public.dir_listing_snapshot(p_id);end if;
 update public.dir_listings set moderation_status='review',
  revision=case when p_log and moderation_status in('clear','approved') then revision+1 else revision end,
  updated_at=case when p_log and moderation_status in('clear','approved') then clock_timestamp() else updated_at end
  where id=p_id and moderation_status in('clear','approved');
 get diagnostics n=row_count;
 if p_log and n>0 then
  insert into public.dir_listing_history(listing_id,action_id,actor_id,action,revision,before,after)
  values(p_id,public.dir_derived_uuid(p_action,'flag:'||p_kind||':'||p_key),coalesce(p_actor,'00000000-0000-0000-0000-000000000000'),'flag',
   (select revision from public.dir_listings where id=p_id),before,public.dir_listing_snapshot(p_id)||jsonb_build_object('flag',p_kind));
 end if;
 return true;
end $$;

-- Price outlier (vehicles): price_crc_norm below price_outlier_pct % of the median of OTHER sellers' listings for
-- the same model and year (published/reserved/sold, moderation clear/approved) with at least
-- price_outlier_min_samples samples. Called inside the owner action (which already bumps the revision).
create or replace function public.dir_listing_price_check(p_id uuid,p_actor uuid,p_action uuid) returns boolean
language plpgsql security invoker set search_path=public,pg_temp as $$
declare l public.dir_listings;v public.dir_listing_vehicle;n integer;med numeric;
begin
 select * into l from public.dir_listings where id=p_id;
 if l.vertical<>'vehiculos' or l.price_crc_norm is null then return false;end if;
 select * into v from public.dir_listing_vehicle where listing_id=p_id;
 select count(*),percentile_cont(0.5) within group(order by o.price_crc_norm) into n,med
  from public.dir_listings o join public.dir_listing_vehicle ov on ov.listing_id=o.id
  where ov.model_id=v.model_id and ov.year=v.year and o.id<>p_id and o.seller_profile_id<>l.seller_profile_id
   and o.status in('published','reserved','sold') and o.moderation_status in('clear','approved') and o.price_crc_norm is not null;
 if n<public.dir_listing_limit('price_outlier_min_samples') or l.price_crc_norm>=med*public.dir_listing_limit('price_outlier_pct')/100.0 then return false;end if;
 return public.dir_listing_flag(p_id,'price_outlier',l.price_crc_norm::text,jsonb_build_object('priceCrcNorm',l.price_crc_norm,'medianCrcNorm',round(med),'samples',n),p_actor,p_action,false);
end $$;

-- Valid status transitions. p_by: owner | staff | system. Renewal (expired→published) is the 'renew' action.
create or replace function public.dir_listing_transition_ok(p_from text,p_to text,p_vertical text,p_operation text,p_by text) returns boolean
language sql immutable parallel safe security invoker set search_path=public,pg_temp as $$
 select coalesce(case p_by
  when 'owner' then
   (p_from='draft' and p_to in('published','archived'))
   or (p_from='published' and p_to in('reserved','draft','archived'))
   or (p_from='reserved' and p_to in('published','archived'))
   or (p_from in('published','reserved') and p_to='sold' and (p_vertical='vehiculos' or p_operation='sale'))
   or (p_from in('published','reserved') and p_to='rented' and p_vertical='inmuebles' and p_operation='rent')
   or (p_from in('expired','sold','rented','suspended') and p_to='archived')
   or (p_from='rented' and p_to='published' and p_vertical='inmuebles' and p_operation='rent')
   or (p_from='archived' and p_to='draft')
  when 'staff' then (p_from<>'suspended' and p_to='suspended') or (p_from='suspended' and p_to in('draft','archived'))
  when 'system' then p_from in('published','reserved') and p_to='expired'
  else false end,false) $$;

-- Deterministic 6-char public code (no 0/1/i/l/o), derived from the listing id; retries on collision.
create or replace function public.dir_listing_code(p_id uuid) returns text
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare alpha constant text:='23456789abcdefghjkmnpqrstuvwxyz';h text;c text;i integer;n integer;
begin
 for n in 0..50 loop
  h:=md5('ccr-listing-code:'||p_id::text||':'||n);c:='';
  for i in 0..5 loop c:=c||substr(alpha,(('x'||substr(h,i*2+1,2))::bit(8)::integer%31)+1,1);end loop;
  if not exists(select 1 from public.dir_listings where public_code=c) then return c;end if;
 end loop;
 raise exception 'Could not allocate a public code' using errcode='40001';
end $$;

-- Public location: fixed offset of 305–495 m in a fixed direction per listing (rounded to 5 decimals).
create or replace function public.dir_listing_fuzz(p_id uuid,p_lat numeric,p_lng numeric) returns table(lat numeric,lng numeric)
language sql immutable parallel safe security invoker set search_path=public,pg_temp as $$
 select case when p_lat is null then null else round(p_lat+degrees(d/6371008.8*cos(t))::numeric,5) end,
        case when p_lat is null then null else round(p_lng+degrees(d/6371008.8*sin(t)/cos(radians(p_lat::double precision)))::numeric,5) end
 from (select 305+(('x'||substr(h,1,4))::bit(16)::integer%191)::double precision d,
              radians((('x'||substr(h,5,4))::bit(16)::integer%3600)/10.0)::double precision t
       from (select md5('ccr-listing-fuzz:'||p_id::text) h) a) b $$;

-- Latest USD→CRC rate on or before a date.
create or replace function public.dir_fx_usd_crc(p_on date) returns table(usd_crc numeric,rate_date date)
language sql stable security invoker set search_path=public,pg_temp as $$
 select r.usd_crc,r.rate_date from public.dir_fx_rates r where r.rate_date<=p_on order by r.rate_date desc limit 1 $$;

create or replace function public.dir_listing_snapshot(p_id uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select to_jsonb(l)||jsonb_build_object(
  'vehicle',(select to_jsonb(v)-'listing_id' from public.dir_listing_vehicle v where v.listing_id=l.id),
  'property',(select to_jsonb(p)-'listing_id' from public.dir_listing_property p where p.listing_id=l.id))
 from public.dir_listings l where l.id=p_id $$;

-- Normalise trimmed fields, place, coordinates and CRC price. Raises 22023 on invalid combinations.
create or replace function public.dir_listing_prepare(p_l public.dir_listings,p_price_changed boolean) returns public.dir_listings
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare l public.dir_listings:=p_l;pl public.dir_places;fx record;
begin
 l.title:=btrim(l.title);l.description:=nullif(btrim(l.description),'');
 l.admin_area_1:=nullif(btrim(l.admin_area_1),'');l.admin_area_2:=nullif(btrim(l.admin_area_2),'');
 l.admin_area_3:=nullif(btrim(l.admin_area_3),'');l.locality:=nullif(btrim(l.locality),'');
 if l.title is null then raise exception 'Title required' using errcode='22023';end if;
 if l.place_id is not null then
  if l.seller_kind<>'business' then raise exception 'Only businesses link a place' using errcode='22023';end if;
  select * into pl from public.dir_places where id=l.place_id;
  if not found or pl.status='removed' or pl.vertical_id<>(array['vehicle_dealer','real_estate'])[array_position(array['vehiculos','inmuebles'],l.vertical)] then
   raise exception 'Invalid place for this listing' using errcode='22023';end if;
 end if;
 if (l.lat is null)<>(l.lng is null) then raise exception 'Invalid coordinates' using errcode='22023';end if;
 if l.country_code='CR' and l.lat is not null and not(l.lat between 5.0 and 11.5 and l.lng between -87.5 and -82.5) then
  raise exception 'Coordinates outside the country' using errcode='22023';end if;
 if l.currency='CRC' then l.price_crc_norm:=l.price_minor;l.fx_rate_date:=null;l.fx_usd_crc:=null;
 elsif p_price_changed then
  select * into fx from public.dir_fx_usd_crc(current_date);
  if fx.usd_crc is null then l.price_crc_norm:=null;l.fx_rate_date:=null;l.fx_usd_crc:=null;
  else l.price_crc_norm:=round(l.price_minor*fx.usd_crc)::bigint;l.fx_rate_date:=fx.rate_date;l.fx_usd_crc:=fx.usd_crc;end if;
 end if;
 return l;
end $$;

create or replace function public.dir_listing_vehicle_prepare(p_v public.dir_listing_vehicle) returns public.dir_listing_vehicle
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v public.dir_listing_vehicle:=p_v;mt text;
begin
 if not exists(select 1 from public.ref_vehicle_makes where id=v.make_id and active) then raise exception 'Unknown make' using errcode='22023';end if;
 select o.vehicle_type into mt from public.ref_vehicle_models o where o.id=v.model_id and o.make_id=v.make_id and o.active;
 if mt is null then raise exception 'Model does not belong to the make' using errcode='22023';end if;
 v.vehicle_type:=mt;
 if v.year is null or v.year>extract(year from current_date)::integer+1 then raise exception 'Invalid year' using errcode='22023';end if;
 if v.condition is null then raise exception 'Condition required' using errcode='22023';end if;
 v.version:=nullif(btrim(v.version),'');v.color:=nullif(btrim(v.color),'');
 v.plate_private:=nullif(upper(btrim(v.plate_private)),'');v.vin_private:=nullif(upper(btrim(v.vin_private)),'');
 return v;
end $$;

create or replace function public.dir_listing_property_prepare(p_p public.dir_listing_property) returns public.dir_listing_property
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare p public.dir_listing_property:=p_p;
begin
 if p.operation is null or p.property_type is null then raise exception 'Operation and property type required' using errcode='22023';end if;
 if p.operation='sale' and p.min_lease_months is not null then raise exception 'Lease terms only for rentals' using errcode='22023';end if;
 p.amenities:=coalesce(p.amenities,'{}');
 p.cadastral_plan_private:=nullif(upper(btrim(p.cadastral_plan_private)),'');p.folio_real_private:=nullif(upper(btrim(p.folio_real_private)),'');
 return p;
end $$;

-- Seller limits (call with the seller lock held). p_entering: status the listing is entering.
create or replace function public.dir_listing_check_limits(p_l public.dir_listings,p_from text,p_to text) returns void
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare n integer;
begin
 if p_l.seller_kind='private' and p_to in('draft','published','reserved') and coalesce(p_from,'') not in('draft','published','reserved') then
  select count(*) into n from public.dir_listings where seller_profile_id=p_l.seller_profile_id and vertical=p_l.vertical and seller_kind='private'
   and status in('draft','published','reserved') and id<>p_l.id;
  if n>=public.dir_listing_limit('private_active_per_vertical') then
   raise exception 'Private sellers have reached their active listing limit' using errcode='54000',hint='dir_listing_limit_private';end if;
 end if;
 if p_l.seller_kind='business' and p_to in('published','reserved') and coalesce(p_from,'') not in('published','reserved')
  and not coalesce((select business_verified from public.dir_listing_sellers where profile_id=p_l.seller_profile_id),false) then
  select count(*) into n from public.dir_listings where seller_profile_id=p_l.seller_profile_id and seller_kind='business'
   and status in('published','reserved') and id<>p_l.id;
  if n>=public.dir_listing_limit('business_unverified_published') then
   raise exception 'Unverified businesses have reached their published listing limit' using errcode='54000',hint='dir_listing_limit_business_unverified';end if;
 end if;
end $$;

-- Requirements to be (or stay) public. Returns the listing with a fresh CRC normalisation for USD prices.
create or replace function public.dir_listing_publish_ready(p_l public.dir_listings) returns public.dir_listings
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare l public.dir_listings;
begin
 if p_l.moderation_status not in('clear','approved') then raise exception 'Listing is under moderation' using errcode='22023',hint='dir_listing_moderation';end if;
 if length(coalesce(p_l.description,''))<20 or p_l.admin_area_1 is null or p_l.admin_area_2 is null then
  raise exception 'Listing incomplete' using errcode='22023',hint='dir_listing_incomplete';end if;
 if (p_l.vertical='vehiculos' and not exists(select 1 from public.dir_listing_vehicle where listing_id=p_l.id))
  or (p_l.vertical='inmuebles' and not exists(select 1 from public.dir_listing_property where listing_id=p_l.id)) then
  raise exception 'Listing incomplete' using errcode='22023',hint='dir_listing_incomplete';end if;
 if public.dir_listing_photo_count(p_l.id)<public.dir_listing_limit('min_photos_publish') then
  raise exception 'Not enough photos to publish' using errcode='22023',hint='dir_listing_photos_missing';end if;
 l:=public.dir_listing_prepare(p_l,true);
 if l.price_crc_norm is null then raise exception 'No USD exchange rate on file' using errcode='22023',hint='dir_listing_fx_missing';end if;
 return l;
end $$;

create or replace function public.dir_listing_result(p_action text,p_id uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('action',p_action,'listingId',l.id,'code',l.public_code,'revision',l.revision,'status',l.status,
  'moderationStatus',l.moderation_status,'publishedAt',l.published_at,'expiresAt',l.expires_at)
 from public.dir_listings l where l.id=p_id $$;

-- ---------------------------------------------------------------- owner actions
-- Input: {action:create|update|status|renew, actionId, listingId, revision, listing?, vehicle?, property?, status?}.
-- p_actor is the seller (profile id). Another seller's listing answers P0002. Route validates with zod first.
create or replace function public.dir_listing_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;lid uuid;rev integer;receipt public.dir_listing_actions;l public.dir_listings;
 v public.dir_listing_vehicle;pr public.dir_listing_property;before jsonb;result jsonb;lm jsonb;vm jsonb;pm jsonb;to_status text;old_status text;
 price_changed boolean:=false;touched boolean:=false;old_place uuid;
 lmap constant jsonb:='{"vertical":"vertical","sellerKind":"seller_kind","placeId":"place_id","title":"title","description":"description","priceMinor":"price_minor","currency":"currency","countryCode":"country_code","adminArea1":"admin_area_1","adminArea2":"admin_area_2","adminArea3":"admin_area_3","locality":"locality","lat":"lat","lng":"lng"}';
 vmap constant jsonb:='{"makeId":"make_id","modelId":"model_id","version":"version","year":"year","condition":"condition","mileageKm":"mileage_km","transmission":"transmission","fuel":"fuel","drivetrain":"drivetrain","engineCc":"engine_cc","doors":"doors","seats":"seats","color":"color","acceptsTradeIn":"accepts_trade_in","sellerFinancing":"seller_financing","marchamoCurrentDeclared":"marchamo_current_declared","rtvCurrentDeclared":"rtv_current_declared","taxesPaidDeclared":"taxes_paid_declared","platePrivate":"plate_private","vinPrivate":"vin_private"}';
 pmap constant jsonb:='{"operation":"operation","propertyType":"property_type","bedrooms":"bedrooms","bathrooms":"bathrooms","parkingSpaces":"parking_spaces","builtM2":"built_m2","lotM2":"lot_m2","floors":"floors","yearBuilt":"year_built","furnished":"furnished","petsAllowed":"pets_allowed","inCondominium":"in_condominium","hoaFeeMinor":"hoa_fee_minor","minLeaseMonths":"min_lease_months","amenities":"amenities","cadastralPlanPrivate":"cadastral_plan_private","folioRealPrivate":"folio_real_private"}';
begin
 if p_actor is null or jsonb_typeof(p_input)<>'object' or act is null or act not in('create','update','status','renew') or jsonb_typeof(p_input->'revision')<>'number' then
  raise exception 'Invalid listing action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'listingId')::uuid;rev:=(p_input->>'revision')::integer;
 exception when others then raise exception 'Invalid listing action' using errcode='22023';end;
 if aid is null or lid is null or rev<0 then raise exception 'Invalid listing action' using errcode='22023';end if;
 -- Seller lock first (limits), then listing lock.
 perform pg_advisory_xact_lock(hashtextextended('dir-seller:'||p_actor::text,0));
 perform pg_advisory_xact_lock(hashtextextended('dir-listing:'||lid::text,0));
 select * into receipt from public.dir_listing_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result;end if;
 select * into l from public.dir_listings where id=lid for update;

 if act='create' then
  if found or rev<>0 then raise exception 'Listing changed' using errcode='40001';end if;
  lm:=public.dir_listing_remap(p_input->'listing',lmap);
  if coalesce(lm->>'vertical','') not in('vehiculos','inmuebles') or coalesce(lm->>'seller_kind','') not in('business','private') then
   raise exception 'Invalid vertical or seller kind' using errcode='22023';end if;
  if (lm->>'vertical'='vehiculos' and (jsonb_typeof(p_input->'vehicle')<>'object' or p_input ? 'property'))
   or (lm->>'vertical'='inmuebles' and (jsonb_typeof(p_input->'property')<>'object' or p_input ? 'vehicle')) then
   raise exception 'Vertical details required' using errcode='22023';end if;
  begin l:=jsonb_populate_record(null::public.dir_listings,lm);
  exception when others then raise exception 'Invalid listing fields' using errcode='22023';end;
  if l.price_minor is null or l.currency is null then raise exception 'Price required' using errcode='22023';end if;
  l.id:=lid;l.seller_profile_id:=p_actor;l.country_code:=coalesce(l.country_code,'CR');l.status:='draft';l.moderation_status:='clear';
  l:=public.dir_listing_prepare(l,true);
  if l.place_id is not null and public.dir_place_manager_role(p_actor,l.place_id) is null then
   raise exception 'You do not manage this place' using errcode='42501',hint='dir_listing_place_not_managed';end if;
  insert into public.dir_listing_sellers(profile_id) values(p_actor) on conflict(profile_id) do nothing;
  perform public.dir_listing_check_limits(l,null,'draft');
  l.public_code:=public.dir_listing_code(lid);
  insert into public.dir_listings(id,public_code,vertical,seller_kind,seller_profile_id,place_id,status,moderation_status,title,description,price_minor,currency,
   price_crc_norm,fx_rate_date,fx_usd_crc,country_code,admin_area_1,admin_area_2,admin_area_3,locality,lat,lng)
  values(l.id,l.public_code,l.vertical,l.seller_kind,l.seller_profile_id,l.place_id,'draft','clear',l.title,l.description,l.price_minor,l.currency,
   l.price_crc_norm,l.fx_rate_date,l.fx_usd_crc,l.country_code,l.admin_area_1,l.admin_area_2,l.admin_area_3,l.locality,l.lat,l.lng) returning * into l;
  if l.vertical='vehiculos' then
   vm:=public.dir_listing_remap(p_input->'vehicle',vmap);
   begin v:=jsonb_populate_record(null::public.dir_listing_vehicle,vm);exception when others then raise exception 'Invalid vehicle fields' using errcode='22023';end;
   v.listing_id:=lid;v.accepts_trade_in:=coalesce(v.accepts_trade_in,false);v.seller_financing:=coalesce(v.seller_financing,false);
   v:=public.dir_listing_vehicle_prepare(v);insert into public.dir_listing_vehicle select v.*;
  else
   pm:=public.dir_listing_remap(p_input->'property',pmap);
   begin pr:=jsonb_populate_record(null::public.dir_listing_property,pm);exception when others then raise exception 'Invalid property fields' using errcode='22023';end;
   pr.listing_id:=lid;pr:=public.dir_listing_property_prepare(pr);insert into public.dir_listing_property select pr.*;
  end if;
 else
  if not found or l.seller_profile_id<>p_actor then raise exception 'Listing not found' using errcode='P0002';end if;
  if l.revision<>rev then raise exception 'Listing changed' using errcode='40001';end if;
  before:=public.dir_listing_snapshot(lid);old_status:=l.status;
  if act='update' then
   if l.status in('sold','rented','suspended') then raise exception 'Listing cannot be edited in this status' using errcode='22023',hint='dir_listing_locked';end if;
   lm:=public.dir_listing_remap(p_input->'listing',lmap-array['vertical','sellerKind','countryCode']);
   if (p_input ? 'vehicle' and l.vertical<>'vehiculos') or (p_input ? 'property' and l.vertical<>'inmuebles') then raise exception 'Wrong vertical details' using errcode='22023';end if;
   if lm<>'{}' then
    price_changed:=lm ?| array['price_minor','currency'];old_place:=l.place_id;
    begin l:=jsonb_populate_record(l,lm);exception when others then raise exception 'Invalid listing fields' using errcode='22023';end;
    if l.title is null or l.price_minor is null or l.currency is null then raise exception 'Required field cleared' using errcode='22023';end if;
    l:=public.dir_listing_prepare(l,price_changed);touched:=true;
    if l.place_id is not null and l.place_id is distinct from old_place and public.dir_place_manager_role(p_actor,l.place_id) is null then
     raise exception 'You do not manage this place' using errcode='42501',hint='dir_listing_place_not_managed';end if;
    -- Unlinking the place drops the agent (an agent belongs to the place's team).
    if l.place_id is null then l.agent_profile_id:=null;end if;
   end if;
   if p_input ? 'vehicle' then
    vm:=public.dir_listing_remap(p_input->'vehicle',vmap);
    if vm<>'{}' then
     select * into v from public.dir_listing_vehicle where listing_id=lid;
     begin v:=jsonb_populate_record(v,vm);exception when others then raise exception 'Invalid vehicle fields' using errcode='22023';end;
     v.accepts_trade_in:=coalesce(v.accepts_trade_in,false);v.seller_financing:=coalesce(v.seller_financing,false);
     v:=public.dir_listing_vehicle_prepare(v);
     update public.dir_listing_vehicle t set make_id=v.make_id,model_id=v.model_id,vehicle_type=v.vehicle_type,version=v.version,year=v.year,condition=v.condition,
      mileage_km=v.mileage_km,transmission=v.transmission,fuel=v.fuel,drivetrain=v.drivetrain,engine_cc=v.engine_cc,doors=v.doors,seats=v.seats,color=v.color,
      accepts_trade_in=v.accepts_trade_in,seller_financing=v.seller_financing,marchamo_current_declared=v.marchamo_current_declared,
      rtv_current_declared=v.rtv_current_declared,taxes_paid_declared=v.taxes_paid_declared,plate_private=v.plate_private,vin_private=v.vin_private where t.listing_id=lid;
     touched:=true;
    end if;
   end if;
   if p_input ? 'property' then
    pm:=public.dir_listing_remap(p_input->'property',pmap);
    if pm<>'{}' then
     select * into pr from public.dir_listing_property where listing_id=lid;
     if pm ? 'operation' and pm->>'operation' is distinct from pr.operation then raise exception 'The operation cannot change' using errcode='22023';end if;
     begin pr:=jsonb_populate_record(pr,pm);exception when others then raise exception 'Invalid property fields' using errcode='22023';end;
     pr:=public.dir_listing_property_prepare(pr);
     update public.dir_listing_property t set property_type=pr.property_type,bedrooms=pr.bedrooms,bathrooms=pr.bathrooms,parking_spaces=pr.parking_spaces,
      built_m2=pr.built_m2,lot_m2=pr.lot_m2,floors=pr.floors,year_built=pr.year_built,furnished=pr.furnished,pets_allowed=pr.pets_allowed,
      in_condominium=pr.in_condominium,hoa_fee_minor=pr.hoa_fee_minor,min_lease_months=pr.min_lease_months,amenities=pr.amenities,
      cadastral_plan_private=pr.cadastral_plan_private,folio_real_private=pr.folio_real_private where t.listing_id=lid;
     touched:=true;
    end if;
   end if;
   if not touched then raise exception 'Nothing to change' using errcode='22023';end if;
   -- A public listing must stay complete.
   if l.status in('published','reserved') then l:=public.dir_listing_publish_ready(l);end if;
   update public.dir_listings set place_id=l.place_id,title=l.title,description=l.description,price_minor=l.price_minor,currency=l.currency,
    price_crc_norm=l.price_crc_norm,fx_rate_date=l.fx_rate_date,fx_usd_crc=l.fx_usd_crc,admin_area_1=l.admin_area_1,admin_area_2=l.admin_area_2,
    admin_area_3=l.admin_area_3,locality=l.locality,lat=l.lat,lng=l.lng,agent_profile_id=l.agent_profile_id,revision=revision+1,updated_at=clock_timestamp() where id=lid returning * into l;
   if price_changed and l.status in('published','reserved') then perform public.dir_listing_price_check(lid,p_actor,aid);end if;
  elsif act='status' then
   to_status:=p_input->>'status';
   if not public.dir_listing_transition_ok(l.status,to_status,l.vertical,(select operation from public.dir_listing_property where listing_id=lid),'owner') then
    raise exception 'Invalid status transition' using errcode='22023',hint='dir_listing_transition';end if;
   perform public.dir_listing_check_limits(l,l.status,to_status);
   if to_status='published' then l:=public.dir_listing_publish_ready(l);end if;
   update public.dir_listings set status=to_status,status_changed_at=clock_timestamp(),
    price_crc_norm=l.price_crc_norm,fx_rate_date=l.fx_rate_date,fx_usd_crc=l.fx_usd_crc,
    published_at=case when to_status='published' then coalesce(published_at,clock_timestamp()) else published_at end,
    expires_at=case when to_status='published' and old_status not in('published','reserved') then clock_timestamp()+interval '60 days' else expires_at end,
    revision=revision+1,updated_at=clock_timestamp() where id=lid returning * into l;
   if to_status='published' then perform public.dir_listing_price_check(lid,p_actor,aid);end if;
  else -- renew: +60 days from now; published_at never changes (no bumping).
   if l.status not in('published','reserved','expired') then raise exception 'Only public or expired listings can be renewed' using errcode='22023',hint='dir_listing_transition';end if;
   if l.status='expired' then perform public.dir_listing_check_limits(l,'expired','published');end if;
   l:=public.dir_listing_publish_ready(l);
   update public.dir_listings set status=case when status='expired' then 'published' else status end,
    status_changed_at=case when status='expired' then clock_timestamp() else status_changed_at end,
    price_crc_norm=l.price_crc_norm,fx_rate_date=l.fx_rate_date,fx_usd_crc=l.fx_usd_crc,
    expires_at=clock_timestamp()+interval '60 days',revision=revision+1,updated_at=clock_timestamp() where id=lid returning * into l;
   perform public.dir_listing_price_check(lid,p_actor,aid);
  end if;
 end if;
 select * into l from public.dir_listings where id=lid;
 insert into public.dir_listing_history(listing_id,action_id,actor_id,action,revision,before,after) values(lid,aid,p_actor,act,l.revision,before,public.dir_listing_snapshot(lid));
 result:=public.dir_listing_result(act,lid);
 insert into public.dir_listing_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- staff actions
-- Input: {action:suspend|reinstate|moderation|seller, actionId, listingId?, revision?, status? (reinstate: draft|archived),
--         moderationStatus? (clear|review|approved|rejected), profileId?, businessVerified?, note?}. Route checks staff first.
create or replace function public.dir_listing_moderate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;lid uuid;pid uuid;rev integer;receipt public.dir_listing_actions;l public.dir_listings;before jsonb;result jsonb;
 to_status text;ms text;note text:=nullif(btrim(coalesce(p_input->>'note','')),'');
begin
 if p_actor is null or jsonb_typeof(p_input)<>'object' or act is null or act not in('suspend','reinstate','moderation','seller') or length(coalesce(note,''))>500 then
  raise exception 'Invalid moderation action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'listingId')::uuid;pid:=(p_input->>'profileId')::uuid;rev:=(p_input->>'revision')::integer;
 exception when others then raise exception 'Invalid moderation action' using errcode='22023';end;
 if aid is null then raise exception 'Invalid moderation action' using errcode='22023';end if;
 if act='seller' then
  if pid is null or jsonb_typeof(p_input->'businessVerified')<>'boolean' then raise exception 'Invalid moderation action' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('dir-seller:'||pid::text,0));
 else
  if lid is null or rev is null or jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid moderation action' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('dir-listing:'||lid::text,0));
 end if;
 select * into receipt from public.dir_listing_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result;end if;
 if act='seller' then
  insert into public.dir_listing_sellers(profile_id,business_verified,verified_by,verified_at,note,updated_at)
  values(pid,(p_input->>'businessVerified')::boolean,case when (p_input->>'businessVerified')::boolean then p_actor end,case when (p_input->>'businessVerified')::boolean then clock_timestamp() end,note,clock_timestamp())
  on conflict(profile_id) do update set business_verified=excluded.business_verified,verified_by=excluded.verified_by,verified_at=excluded.verified_at,note=excluded.note,updated_at=excluded.updated_at;
  result:=jsonb_build_object('action','seller','profileId',pid,'businessVerified',(p_input->>'businessVerified')::boolean);
 else
  select * into l from public.dir_listings where id=lid for update;
  if not found then raise exception 'Listing not found' using errcode='P0002';end if;
  if l.revision<>rev then raise exception 'Listing changed' using errcode='40001';end if;
  before:=public.dir_listing_snapshot(lid);
  if act in('suspend','reinstate') then
   to_status:=case when act='suspend' then 'suspended' else coalesce(p_input->>'status','draft') end;
   if not public.dir_listing_transition_ok(l.status,to_status,l.vertical,null,'staff') then
    raise exception 'Invalid status transition' using errcode='22023',hint='dir_listing_transition';end if;
   update public.dir_listings set status=to_status,status_changed_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where id=lid;
  else
   ms:=p_input->>'moderationStatus';
   if ms is null or ms not in('clear','review','approved','rejected') or ms=l.moderation_status then raise exception 'Invalid moderation status' using errcode='22023';end if;
   update public.dir_listings set moderation_status=ms,revision=revision+1,updated_at=clock_timestamp() where id=lid;
  end if;
  insert into public.dir_listing_history(listing_id,action_id,actor_id,action,revision,before,after)
   values(lid,aid,p_actor,act,(select revision from public.dir_listings where id=lid),before,public.dir_listing_snapshot(lid)||jsonb_build_object('note',note));
  result:=public.dir_listing_result(act,lid);
 end if;
 insert into public.dir_listing_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Marks due listings as expired (no cron needed: readers already hide them by expires_at). Returns how many.
create or replace function public.dir_listing_expire_due(p_actor uuid,p_limit integer default 500) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r record;n integer:=0;before jsonb;
begin
 if p_actor is null or p_limit is null or p_limit not between 1 and 5000 then raise exception 'Invalid expiry run' using errcode='22023';end if;
 for r in select id,revision from public.dir_listings where status in('published','reserved') and expires_at<=clock_timestamp() order by expires_at limit p_limit for update skip locked loop
  before:=public.dir_listing_snapshot(r.id);
  update public.dir_listings set status='expired',status_changed_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where id=r.id;
  insert into public.dir_listing_history(listing_id,action_id,actor_id,action,revision,before,after)
   values(r.id,public.dir_derived_uuid(r.id,'expire:'||r.revision),p_actor,'expire',r.revision+1,before,public.dir_listing_snapshot(r.id));
  n:=n+1;
 end loop;
 return n;
end $$;

-- ---------------------------------------------------------------- exchange rates (staff / BCCR import)
-- Input: {date:'YYYY-MM-DD', usdCrc:number, source:'bccr'|'manual'}. Upsert; listings keep the rate they were priced with
-- until dir_listing_fx_refresh or a price edit / publish / renew.
create or replace function public.dir_fx_rate_set(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare d date;r numeric;s text:=p_input->>'source';
begin
 if p_actor is null or jsonb_typeof(p_input)<>'object' or jsonb_typeof(p_input->'usdCrc')<>'number' or s is null or s not in('bccr','manual') then raise exception 'Invalid exchange rate' using errcode='22023';end if;
 begin d:=(p_input->>'date')::date;r:=(p_input->>'usdCrc')::numeric;exception when others then raise exception 'Invalid exchange rate' using errcode='22023';end;
 if d is null or d>current_date+1 or r<=0 or r>=100000 then raise exception 'Invalid exchange rate' using errcode='22023';end if;
 insert into public.dir_fx_rates(rate_date,usd_crc,source,recorded_by) values(d,r,s,p_actor)
 on conflict(rate_date) do update set usd_crc=excluded.usd_crc,source=excluded.source,recorded_by=excluded.recorded_by,recorded_at=clock_timestamp();
 return jsonb_build_object('date',d,'usdCrc',r,'source',s);
end $$;
-- Re-normalise USD prices of live listings with the latest rate (derived field: no revision bump, no history).
create or replace function public.dir_listing_fx_refresh(p_actor uuid) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare fx record;n integer;
begin
 if p_actor is null then raise exception 'Invalid refresh' using errcode='22023';end if;
 select * into fx from public.dir_fx_usd_crc(current_date);
 if fx.usd_crc is null then return 0;end if;
 update public.dir_listings set price_crc_norm=round(price_minor*fx.usd_crc)::bigint,fx_rate_date=fx.rate_date,fx_usd_crc=fx.usd_crc
  where currency='USD' and status in('draft','published','reserved') and fx_rate_date is distinct from fx.rate_date;
 get diagnostics n=row_count;return n;
end $$;

-- ---------------------------------------------------------------- V3 photos (seller only)
-- Input: {action:add|remove|reorder, actionId, listingId, media?, mediaId?, order?}.
--  add:     media {id, sha256, width, height, path1600, path800, path320, exifStripped:true, altEs?, altEn?} → appended last.
--  remove:  mediaId. A public listing never drops below min_photos_publish (dir_listing_photos_missing).
--  reorder: order = every active media id exactly once, in the new order.
-- Photos do NOT bump the listing revision (parallel uploads must not conflict); they are serialised by the listing
-- lock and idempotent by actionId. Adding a photo whose sha256 already belongs to ANOTHER seller's listing flags
-- this listing (duplicate_photo → moderation 'review', revision bump + history 'flag').
create or replace function public.dir_listing_media_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;lid uuid;mid uuid;receipt public.dir_listing_actions;l public.dir_listings;m jsonb:=p_input->'media';
 n integer;cur public.dir_listing_media;other text;ids uuid[];result jsonb;
begin
 if p_actor is null or jsonb_typeof(p_input)<>'object' or act is null or act not in('add','remove','reorder')
  or exists(select 1 from jsonb_object_keys(p_input) k where k not in('action','actionId','listingId','media','mediaId','order'))
  or (act='add')<>(p_input ? 'media') or (act='remove')<>(p_input ? 'mediaId') or (act='reorder')<>(p_input ? 'order') then
  raise exception 'Invalid photo action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'listingId')::uuid;
 exception when others then raise exception 'Invalid photo action' using errcode='22023';end;
 if aid is null or lid is null then raise exception 'Invalid photo action' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('dir-listing:'||lid::text,0));
 select * into receipt from public.dir_listing_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result;end if;
 select * into l from public.dir_listings where id=lid for update;
 if not found or l.seller_profile_id<>p_actor then raise exception 'Listing not found' using errcode='P0002';end if;
 if l.status in('sold','rented','suspended') then raise exception 'Listing cannot be edited in this status' using errcode='22023',hint='dir_listing_locked';end if;
 n:=public.dir_listing_photo_count(lid);
 if act='add' then
  if jsonb_typeof(m)<>'object' or exists(select 1 from jsonb_object_keys(m) k where k not in('id','sha256','width','height','path1600','path800','path320','exifStripped','altEs','altEn'))
   or jsonb_typeof(m->'width')<>'number' or jsonb_typeof(m->'height')<>'number' or jsonb_typeof(m->'exifStripped')<>'boolean' then
   raise exception 'Invalid photo' using errcode='22023';end if;
  if not (m->>'exifStripped')::boolean then raise exception 'Photo metadata must be removed' using errcode='22023',hint='dir_listing_media_exif';end if;
  mid:=public.dir_try_uuid(m->>'id');
  if mid is null or coalesce(m->>'sha256','')!~'^[a-f0-9]{64}$' then raise exception 'Invalid photo' using errcode='22023';end if;
  if exists(select 1 from public.dir_listing_media where id=mid) then raise exception 'Photo id already used' using errcode='23505';end if;
  if n>=30 then raise exception 'Photo limit reached' using errcode='54000',hint='dir_listing_media_cap';end if;
  if exists(select 1 from public.dir_listing_media where listing_id=lid and sha256=m->>'sha256' and status='active') then
   raise exception 'This photo is already in the listing' using errcode='23505',hint='dir_listing_media_duplicate';end if;
  begin
   insert into public.dir_listing_media(id,listing_id,sort,sha256,width,height,path_1600,path_800,path_320,exif_stripped,alt_es,alt_en,uploaded_by)
   values(mid,lid,n,m->>'sha256',(m->>'width')::integer,(m->>'height')::integer,m->>'path1600',m->>'path800',m->>'path320',true,
    nullif(btrim(coalesce(m->>'altEs','')),''),nullif(btrim(coalesce(m->>'altEn','')),''),p_actor);
  exception when check_violation or invalid_text_representation or numeric_value_out_of_range then raise exception 'Invalid photo' using errcode='22023';end;
  -- Same image already used by another seller (any status: copying a removed photo is still suspicious).
  select o.public_code into other from public.dir_listing_media x join public.dir_listings o on o.id=x.listing_id
   where x.sha256=m->>'sha256' and o.seller_profile_id<>p_actor order by x.created_at limit 1;
  if other is not null then perform public.dir_listing_flag(lid,'duplicate_photo',m->>'sha256',jsonb_build_object('otherCode',other),p_actor,aid,true);end if;
 elsif act='remove' then
  mid:=public.dir_try_uuid(p_input->>'mediaId');
  select * into cur from public.dir_listing_media where id=mid and listing_id=lid and status='active' for update;
  if not found then raise exception 'Photo not found' using errcode='P0002';end if;
  if l.status in('published','reserved') and n-1<public.dir_listing_limit('min_photos_publish') then
   raise exception 'A public listing needs its minimum photos' using errcode='22023',hint='dir_listing_photos_missing';end if;
  update public.dir_listing_media set status='removed',sort=null,removed_by=p_actor,removed_at=clock_timestamp() where id=mid;
  update public.dir_listing_media set sort=sort-1 where listing_id=lid and status='active' and sort>cur.sort;
 else
  if jsonb_typeof(p_input->'order')<>'array' then raise exception 'Invalid photo order' using errcode='22023';end if;
  begin select array_agg(e::uuid order by o) into ids from jsonb_array_elements_text(p_input->'order') with ordinality t(e,o);
  exception when others then raise exception 'Invalid photo order' using errcode='22023';end;
  if coalesce(cardinality(ids),0)<>n or (select count(distinct x) from unnest(ids) x)<>n
   or exists(select 1 from unnest(ids) x where not exists(select 1 from public.dir_listing_media where id=x and listing_id=lid and status='active')) then
   raise exception 'Invalid photo order' using errcode='22023';end if;
  update public.dir_listing_media d set sort=t.o-1 from unnest(ids) with ordinality t(x,o) where d.id=t.x;
 end if;
 select jsonb_build_object('action',act,'listingId',lid,'photoCount',public.dir_listing_photo_count(lid),'moderationStatus',(select moderation_status from public.dir_listings where id=lid),
  'revision',(select revision from public.dir_listings where id=lid),
  'photos',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'sort',x.sort) order by x.sort) from public.dir_listing_media x where x.listing_id=lid and x.status='active'),'[]')) into result;
 insert into public.dir_listing_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- R2 agent assignment
-- Input: {action:'assign_agent', actionId, listingId, revision, agentId|null}. Only an active owner/manager of the
-- listing's place (others: P0002). The agent must hold role admin/manager/member in the Pro team of the place OWNER
-- (pro_role_of; the owner is admin of their own team). CAS revision, receipt, history 'assign_agent'.
create or replace function public.dir_listing_assign_agent(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;lid uuid;rev integer;agent uuid;receipt public.dir_listing_actions;l public.dir_listings;owner_id uuid;r text;before jsonb;result jsonb;
begin
 if p_actor is null or jsonb_typeof(p_input)<>'object' or p_input->>'action' is distinct from 'assign_agent' or jsonb_typeof(p_input->'revision')<>'number'
  or not (p_input ? 'agentId') or jsonb_typeof(p_input->'agentId') not in('string','null')
  or exists(select 1 from jsonb_object_keys(p_input) k where k not in('action','actionId','listingId','revision','agentId')) then
  raise exception 'Invalid agent assignment' using errcode='22023';end if;
 aid:=public.dir_try_uuid(p_input->>'actionId');lid:=public.dir_try_uuid(p_input->>'listingId');agent:=public.dir_try_uuid(p_input->>'agentId');
 begin rev:=(p_input->>'revision')::integer;exception when others then raise exception 'Invalid agent assignment' using errcode='22023';end;
 if aid is null or lid is null or rev<1 or (jsonb_typeof(p_input->'agentId')='string' and agent is null) then raise exception 'Invalid agent assignment' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('dir-listing:'||lid::text,0));
 select * into receipt from public.dir_listing_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result;end if;
 select * into l from public.dir_listings where id=lid for update;
 if not found or l.place_id is null or public.dir_place_manager_role(p_actor,l.place_id) is null then raise exception 'Listing not found' using errcode='P0002';end if;
 if l.vertical<>'inmuebles' then raise exception 'Agents apply to property listings only' using errcode='22023',hint='dir_listing_agent_vertical';end if;
 if l.revision<>rev then raise exception 'Listing changed' using errcode='40001';end if;
 if l.status='suspended' then raise exception 'Listing cannot be edited in this status' using errcode='22023',hint='dir_listing_locked';end if;
 if agent is not distinct from l.agent_profile_id then raise exception 'Nothing to change' using errcode='22023';end if;
 if agent is not null then
  if to_regprocedure('public.pro_role_of(uuid,uuid)') is null then
   raise exception 'Team module unavailable' using errcode='55000',hint='dir_listing_team_unavailable';end if;
  select user_id into owner_id from public.dir_place_managers where place_id=l.place_id and role='owner' and status='active';
  if owner_id is not null then execute 'select public.pro_role_of($1,$2)' into r using agent,owner_id;end if;
  if r is null or r not in('admin','manager','member') then
   raise exception 'The agent is not an active member of the team' using errcode='22023',hint='dir_listing_agent_not_member';end if;
 end if;
 before:=public.dir_listing_snapshot(lid);
 update public.dir_listings set agent_profile_id=agent,revision=revision+1,updated_at=clock_timestamp() where id=lid;
 insert into public.dir_listing_history(listing_id,action_id,actor_id,action,revision,before,after)
  values(lid,aid,p_actor,'assign_agent',rev+1,before,public.dir_listing_snapshot(lid));
 result:=public.dir_listing_result('assign_agent',lid)||jsonb_build_object('agentId',agent);
 insert into public.dir_listing_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- declared financing (per dealer place)
-- Input: {actionId, placeId, revision (0 = first declaration), financing:{annualRatePct, maxTermMonths, minDownPaymentPct}|null}.
-- null withdraws it. Owner/manager of a vehicle_dealer place only (others: P0002). Every save refreshes declared_at.
create or replace function public.dir_listing_financing_set(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;pid uuid;rev integer;f jsonb:=p_input->'financing';receipt public.dir_listing_actions;cur public.dir_listing_financing;pl public.dir_places;
 rate numeric;term integer;down numeric;result jsonb;
begin
 if p_actor is null or jsonb_typeof(p_input)<>'object' or jsonb_typeof(p_input->'revision')<>'number' or not (p_input ? 'financing') or jsonb_typeof(f) not in('object','null')
  or exists(select 1 from jsonb_object_keys(p_input) k where k not in('actionId','placeId','revision','financing')) then
  raise exception 'Invalid financing' using errcode='22023';end if;
 aid:=public.dir_try_uuid(p_input->>'actionId');pid:=public.dir_try_uuid(p_input->>'placeId');
 begin rev:=(p_input->>'revision')::integer;exception when others then raise exception 'Invalid financing' using errcode='22023';end;
 if aid is null or pid is null or rev<0 then raise exception 'Invalid financing' using errcode='22023';end if;
 if jsonb_typeof(f)='object' then
  if exists(select 1 from jsonb_object_keys(f) k where k not in('annualRatePct','maxTermMonths','minDownPaymentPct'))
   or jsonb_typeof(f->'annualRatePct')<>'number' or jsonb_typeof(f->'maxTermMonths')<>'number' or jsonb_typeof(f->'minDownPaymentPct')<>'number' then
   raise exception 'Invalid financing' using errcode='22023';end if;
  rate:=(f->>'annualRatePct')::numeric;term:=null;down:=(f->>'minDownPaymentPct')::numeric;
  if (f->>'maxTermMonths')::numeric=trunc((f->>'maxTermMonths')::numeric) then term:=(f->>'maxTermMonths')::numeric::integer;end if;
  if rate<0 or rate>60 or rate<>round(rate,2) or term is null or term not between 1 and 120 or down<0 or down>90 or down<>round(down,2) then
   raise exception 'Financing values out of range' using errcode='22023',hint='dir_listing_financing_range';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('dir-financing:'||pid::text,0));
 select * into receipt from public.dir_listing_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result;end if;
 select * into pl from public.dir_places where id=pid;
 if not found or pl.status='removed' or pl.vertical_id<>'vehicle_dealer' or public.dir_place_manager_role(p_actor,pid) is null then
  raise exception 'Place not found' using errcode='P0002';end if;
 select * into cur from public.dir_listing_financing where place_id=pid for update;
 if coalesce(cur.revision,0)<>rev then raise exception 'Financing changed' using errcode='40001';end if;
 if f is null or jsonb_typeof(f)='null' then
  if not found or cur.status='withdrawn' then raise exception 'Nothing to withdraw' using errcode='22023';end if;
  update public.dir_listing_financing set status='withdrawn',revision=revision+1,updated_at=clock_timestamp() where place_id=pid returning * into cur;
 elsif not found then
  insert into public.dir_listing_financing(place_id,annual_rate_pct,max_term_months,min_down_payment_pct,declared_by) values(pid,rate,term,down,p_actor) returning * into cur;
 else
  update public.dir_listing_financing set annual_rate_pct=rate,max_term_months=term,min_down_payment_pct=down,status='active',declared_by=p_actor,
   declared_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where place_id=pid returning * into cur;
 end if;
 result:=jsonb_build_object('placeId',pid,'revision',cur.revision,'status',cur.status,'annualRatePct',cur.annual_rate_pct,'maxTermMonths',cur.max_term_months,
  'minDownPaymentPct',cur.min_down_payment_pct,'declaredAt',cur.declared_at,'declaredBySeller',true);
 insert into public.dir_listing_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- public reports (reuse dir_reports)
-- Input: {reportId, kind: wrong_info|duplicate|abuse|other, message, email?}. Only listings that are currently public.
-- Caps: 20 per listing a day, 5 a day per contact e-mail (shared with place reports) → 54000 dir_listing_report_cap.
-- reports_to_review distinct identified reporters (account or e-mail) of open 'abuse' reports in 7 days flag the
-- listing ('reports' → review). Same reportId + same input → same answer.
create or replace function public.dir_listing_report_create(p_actor uuid,p_code text,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare rid uuid;l public.dir_listings;prior public.dir_reports;h text;mail text;answer jsonb:=jsonb_build_object('ok',true);n integer;t integer;
begin
 if jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in('reportId','kind','message','email')) then
  raise exception 'Invalid report' using errcode='22023';end if;
 rid:=public.dir_try_uuid(p_input->>'reportId');
 mail:=nullif(lower(btrim(coalesce(p_input->>'email',''))),'');
 if rid is null or coalesce(p_input->>'kind','') not in('wrong_info','duplicate','abuse','other')
  or length(btrim(coalesce(p_input->>'message',''))) not between 5 and 2000 or (mail is not null and (mail!~'^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(mail)>254)) then
  raise exception 'Invalid report' using errcode='22023';end if;
 if p_code is null or p_code!~'^[2-9a-hjkmnp-z]{6}$' or public.dir_listing_public(p_code) is null then raise exception 'Listing unavailable' using errcode='P0002';end if;
 select * into l from public.dir_listings where public_code=p_code;
 h:=encode(sha256(convert_to(jsonb_build_object('code',p_code,'actor',p_actor,'kind',p_input->>'kind','message',btrim(p_input->>'message'),'email',mail)::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('dir-listing:'||l.id::text,0));
 select * into prior from public.dir_reports where id=rid;
 if found then if prior.input_hash<>h then raise exception 'Report id reused' using errcode='22023';end if;return answer;end if;
 if (select count(*) from public.dir_reports r where r.listing_id=l.id and r.created_at>clock_timestamp()-interval '1 day')>=20
  or (mail is not null and (select count(*) from public.dir_reports r where r.contact_email=mail and r.created_at>clock_timestamp()-interval '1 day')>=5) then
  raise exception 'Too many reports' using errcode='54000',hint='dir_listing_report_cap';end if;
 insert into public.dir_reports(id,place_id,listing_id,kind,message,contact_email,reporter_id,input_hash) values(rid,null,l.id,p_input->>'kind',btrim(p_input->>'message'),mail,p_actor,h);
 if p_input->>'kind'='abuse' then
  t:=public.dir_listing_limit('reports_to_review');
  select count(distinct coalesce(r.reporter_id::text,r.contact_email)) into n from public.dir_reports r
   where r.listing_id=l.id and r.kind='abuse' and r.status='open' and r.created_at>clock_timestamp()-interval '7 days' and coalesce(r.reporter_id::text,r.contact_email) is not null;
  if n>=t then perform public.dir_listing_flag(l.id,'reports','abuse:'||(n/t)::text,jsonb_build_object('reporters',n),p_actor,rid,true);end if;
 end if;
 return answer;
end $$;

-- Staff queue: listings under review with their flags and open reports (oldest first). The route checks staff + MFA.
create or replace function public.dir_listing_review_queue(p_limit integer default 50) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(x.j order by x.updated_at,x.id),'[]') from (
  select l.id,l.updated_at,jsonb_build_object('listingId',l.id,'code',l.public_code,'vertical',l.vertical,'status',l.status,'revision',l.revision,
   'title',l.title,'priceMinor',l.price_minor,'currency',l.currency,'priceCrcNorm',l.price_crc_norm,
   'flags',coalesce((select jsonb_agg(jsonb_build_object('kind',f.kind,'key',f.key,'detail',f.detail,'at',f.created_at) order by f.id) from public.dir_listing_flags f where f.listing_id=l.id),'[]'),
   'openReports',(select count(*) from public.dir_reports r where r.listing_id=l.id and r.status='open')) j
  from public.dir_listings l where l.moderation_status='review'
  order by l.updated_at,l.id limit least(greatest(coalesce(p_limit,50),1),200)) x $$;

-- ---------------------------------------------------------------- Pro inventory reader
-- One inventory item. Private fields (plate, VIN, plano, folio, exact lat/lng) only when p_actor is the seller.
create or replace function public.dir_listing_owner_item(p_id uuid,p_actor uuid,p_status text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',l.id,'code',l.public_code,'revision',l.revision,'status',p_status,'moderationStatus',l.moderation_status,
  'title',l.title,'description',l.description,'priceMinor',l.price_minor,'currency',l.currency,'priceCrcNorm',l.price_crc_norm,'fxRateDate',l.fx_rate_date,
  'adminArea1',l.admin_area_1,'adminArea2',l.admin_area_2,'adminArea3',l.admin_area_3,'locality',l.locality,
  'lat',case when mine then l.lat end,'lng',case when mine then l.lng end,
  'placeId',l.place_id,'agentId',l.agent_profile_id,'sellerKind',l.seller_kind,'mine',mine,'canEdit',mine,
  'photoCount',public.dir_listing_photo_count(l.id),
  'photos',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'sort',m.sort,'path1600',m.path_1600,'path800',m.path_800,'path320',m.path_320,
    'width',m.width,'height',m.height,'altEs',m.alt_es,'altEn',m.alt_en) order by m.sort) from public.dir_listing_media m where m.listing_id=l.id and m.status='active'),'[]'),
  'publishedAt',l.published_at,'expiresAt',l.expires_at,'updatedAt',l.updated_at,
  'vehicle',(select jsonb_build_object('makeId',v.make_id,'modelId',v.model_id,'vehicleType',v.vehicle_type,'version',v.version,'year',v.year,'condition',v.condition,
    'mileageKm',v.mileage_km,'transmission',v.transmission,'fuel',v.fuel,'drivetrain',v.drivetrain,'engineCc',v.engine_cc,'doors',v.doors,'seats',v.seats,
    'color',v.color,'acceptsTradeIn',v.accepts_trade_in,'sellerFinancing',v.seller_financing,'marchamoCurrentDeclared',v.marchamo_current_declared,
    'rtvCurrentDeclared',v.rtv_current_declared,'taxesPaidDeclared',v.taxes_paid_declared,
    'platePrivate',case when mine then v.plate_private end,'vinPrivate',case when mine then v.vin_private end)
   from public.dir_listing_vehicle v where v.listing_id=l.id),
  'property',(select jsonb_build_object('operation',p.operation,'propertyType',p.property_type,'bedrooms',p.bedrooms,'bathrooms',p.bathrooms,
    'parkingSpaces',p.parking_spaces,'builtM2',p.built_m2,'lotM2',p.lot_m2,'floors',p.floors,'yearBuilt',p.year_built,'furnished',p.furnished,
    'petsAllowed',p.pets_allowed,'inCondominium',p.in_condominium,'hoaFeeMinor',p.hoa_fee_minor,'minLeaseMonths',p.min_lease_months,'amenities',to_jsonb(p.amenities),
    'cadastralPlanPrivate',case when mine then p.cadastral_plan_private end,'folioRealPrivate',case when mine then p.folio_real_private end)
   from public.dir_listing_property p where p.listing_id=l.id))
 from public.dir_listings l cross join lateral (select l.seller_profile_id=p_actor as mine) o where l.id=p_id $$;

-- Inventory page (shape of inventoryPageSchema). Items: the actor's own listings of the vertical plus listings
-- linked to places the actor manages (read-only for co-managers: canEdit=false, no private fields).
-- p_filter: active (draft/published/reserved) | closed (sold/rented/archived/suspended/expired). Published or
-- reserved rows past expires_at are reported as 'expired' (closed). Keyset pagination on (updated_at desc, id desc);
-- nextCursor = '<updated_at epoch µs>_<id>' or null.
create or replace function public.dir_listing_owner_list(p_actor uuid,p_vertical text,p_filter text default 'active',p_cursor text default null,p_limit integer default 50) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ptype text;lim integer:=coalesce(p_limit,50);cur_ts timestamptz;cur_id uuid;r record;n integer:=0;items jsonb:='[]';nxt text;last_ts timestamptz;last_id uuid;
 places jsonb;agents jsonb:='[]';fin jsonb;catalog jsonb;kind text;
begin
 if p_actor is null or p_vertical is null or p_vertical not in('vehiculos','inmuebles') or coalesce(p_filter,'') not in('active','closed') or lim not between 1 and 100 then
  raise exception 'Invalid inventory query' using errcode='22023';end if;
 if p_cursor is not null then
  if p_cursor!~'^[0-9]{1,20}_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'Invalid cursor' using errcode='22023',hint='dir_listing_cursor';end if;
  cur_ts:='epoch'::timestamptz+(split_part(p_cursor,'_',1)||' microseconds')::interval;cur_id:=split_part(p_cursor,'_',2)::uuid;
 end if;
 ptype:=case p_vertical when 'vehiculos' then 'vehicle_dealer' else 'real_estate' end;
 places:=coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'slug',p.slug,'role',m.role,'placeStatus',p.status) order by p.name,p.id)
  from public.dir_place_managers m join public.dir_places p on p.id=m.place_id
  where m.user_id=p_actor and m.status='active' and p.vertical_id=ptype and p.status<>'removed'),'[]');
 if p_vertical='inmuebles' and to_regclass('public.pro_company_members') is not null and to_regclass('public.profiles') is not null then
  execute $q$select coalesce(jsonb_agg(jsonb_build_object('id',x.member_user_id,'name',x.name,'placeIds',x.place_ids) order by x.name,x.member_user_id),'[]') from (
    select c.member_user_id,min(coalesce(nullif(btrim(c.member_name),''),c.member_email)) as name,jsonb_agg(distinct o.place_id) as place_ids
    from public.dir_place_managers me
    join public.dir_places p on p.id=me.place_id and p.vertical_id='real_estate' and p.status<>'removed'
    join public.dir_place_managers o on o.place_id=me.place_id and o.role='owner' and o.status='active'
    join public.pro_company_members c on c.owner_id=o.user_id and c.active and c.role in('admin','manager','member')
    join public.profiles pf on pf.id=c.member_user_id and not coalesce(pf.is_disabled,false)
    where me.user_id=$1 and me.status='active' group by c.member_user_id) x$q$ into agents using p_actor;
 end if;
 if p_vertical='vehiculos' then
  catalog:=jsonb_build_object(
   'makes',coalesce((select jsonb_agg(jsonb_build_object('id',k.id,'name',k.name,'slug',k.slug) order by k.name,k.id) from public.ref_vehicle_makes k where k.active),'[]'),
   'models',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'makeId',o.make_id,'name',o.name,'slug',o.slug,'vehicleType',o.vehicle_type) order by o.name,o.id)
     from public.ref_vehicle_models o join public.ref_vehicle_makes k on k.id=o.make_id and k.active where o.active),'[]'));
  fin:=coalesce((select jsonb_agg(jsonb_build_object('placeId',f.place_id,'revision',f.revision,'status',f.status,'annualRatePct',f.annual_rate_pct,
    'maxTermMonths',f.max_term_months,'minDownPaymentPct',f.min_down_payment_pct,'declaredAt',f.declared_at,
    'stale',f.declared_at<=clock_timestamp()-make_interval(days=>public.dir_listing_limit('financing_max_age_days'))) order by f.place_id)
   from public.dir_listing_financing f where f.place_id in(select (e->>'id')::uuid from jsonb_array_elements(places) e)),'[]');
 end if;
 for r in
  select x.id,x.updated_at,x.eff from (
   select l.id,l.updated_at,case when l.status in('published','reserved') and l.expires_at<=now() then 'expired' else l.status end as eff
   from public.dir_listings l
   where l.vertical=p_vertical and (l.seller_profile_id=p_actor
    or l.place_id in(select m.place_id from public.dir_place_managers m where m.user_id=p_actor and m.status='active'))) x
  where (case when p_filter='active' then x.eff in('draft','published','reserved') else x.eff in('sold','rented','archived','suspended','expired') end)
   and (cur_ts is null or (x.updated_at,x.id)<(cur_ts,cur_id))
  order by x.updated_at desc,x.id desc limit lim+1
 loop
  n:=n+1;
  if n>lim then nxt:=((extract(epoch from last_ts)*1000000)::bigint)::text||'_'||last_id::text;exit;end if;
  items:=items||jsonb_build_array(public.dir_listing_owner_item(r.id,p_actor,r.eff));last_ts:=r.updated_at;last_id:=r.id;
 end loop;
 kind:=case when jsonb_array_length(places)>0 or exists(select 1 from public.dir_listings where seller_profile_id=p_actor and seller_kind='business') then 'business' else 'private' end;
 return jsonb_build_object('vertical',p_vertical,'filter',p_filter,'sellerKind',kind,
  'businessVerified',coalesce((select business_verified from public.dir_listing_sellers where profile_id=p_actor),false),
  'limits',jsonb_build_object('privateActivePerVertical',public.dir_listing_limit('private_active_per_vertical'),
   'businessUnverifiedPublished',public.dir_listing_limit('business_unverified_published'),'minPhotosToPublish',public.dir_listing_limit('min_photos_publish'),'maxPhotos',30),
  'counts',jsonb_build_object(
   'active',(select count(*) from public.dir_listings where seller_profile_id=p_actor and vertical=p_vertical and status in('draft','published','reserved')),
   'published',(select count(*) from public.dir_listings where seller_profile_id=p_actor and vertical=p_vertical and status in('published','reserved') and expires_at>now())),
  'places',places,'agents',agents,'catalog',catalog,'financing',fin,'items',items,'nextCursor',nxt);
end $$;

-- ---------------------------------------------------------------- public readers
-- No internal ids, seller ids, revision, exact coordinates or *_private fields. Only published or reserved
-- (status column → «Reservado» badge, CTAs off, noindex), unexpired and moderation clear/approved; drafts, sold,
-- rented, archived, suspended, expired and listings under review stay hidden. No ORDER BY here: callers order by
-- neutral keys (published_at, price, distance). photo_count / cover paths come from dir_listing_media.
create or replace view public.public_vehicle_listings with (security_invoker=true) as
select l.public_code as code,l.seller_kind,
 case when p.status in('published','closed_permanently') then p.slug end as place_slug,
 case when p.status in('published','closed_permanently') then p.name end as place_name,
 (l.seller_kind='business' and coalesce(s.business_verified,false)) as seller_business_verified,
 l.title,l.description,l.price_minor,l.currency,l.price_crc_norm,l.fx_rate_date,
 l.country_code,l.admin_area_1,l.admin_area_2,l.admin_area_3,l.locality,f.lat as approx_lat,f.lng as approx_lng,
 case when f.lat is null then null else 500 end as location_radius_m,
 l.published_at,l.expires_at,l.updated_at,
 mk.slug as make_slug,mk.name as make_name,md.slug as model_slug,md.name as model_name,v.vehicle_type,v.version,v.year,v.condition,
 v.mileage_km,v.transmission,v.fuel,v.drivetrain,v.engine_cc,v.doors,v.seats,v.color,v.accepts_trade_in,v.seller_financing,
 v.marchamo_current_declared,v.rtv_current_declared,v.taxes_paid_declared,
 l.status,ph.n as photo_count,ph.c800 as cover_path_800,ph.c320 as cover_path_320
from public.dir_listings l
join public.dir_listing_vehicle v on v.listing_id=l.id
join public.ref_vehicle_makes mk on mk.id=v.make_id
join public.ref_vehicle_models md on md.id=v.model_id
left join public.dir_places p on p.id=l.place_id
left join public.dir_listing_sellers s on s.profile_id=l.seller_profile_id
cross join lateral public.dir_listing_fuzz(l.id,l.lat,l.lng) f
cross join lateral (select count(*)::integer n,(array_agg(m.path_800 order by m.sort))[1] c800,(array_agg(m.path_320 order by m.sort))[1] c320
 from public.dir_listing_media m where m.listing_id=l.id and m.status='active') ph
where l.vertical='vehiculos' and l.status in('published','reserved') and l.moderation_status in('clear','approved') and l.expires_at>now();

create or replace view public.public_property_listings with (security_invoker=true) as
select l.public_code as code,l.seller_kind,
 case when p.status in('published','closed_permanently') then p.slug end as place_slug,
 case when p.status in('published','closed_permanently') then p.name end as place_name,
 (l.seller_kind='business' and coalesce(s.business_verified,false)) as seller_business_verified,
 l.title,l.description,l.price_minor,l.currency,l.price_crc_norm,l.fx_rate_date,
 l.country_code,l.admin_area_1,l.admin_area_2,l.admin_area_3,l.locality,f.lat as approx_lat,f.lng as approx_lng,
 case when f.lat is null then null else 500 end as location_radius_m,
 l.published_at,l.expires_at,l.updated_at,
 pr.operation,pr.property_type,pr.bedrooms,pr.bathrooms,pr.parking_spaces,pr.built_m2,pr.lot_m2,pr.floors,pr.year_built,
 pr.furnished,pr.pets_allowed,pr.in_condominium,pr.hoa_fee_minor,pr.min_lease_months,pr.amenities,
 l.status,ph.n as photo_count,ph.c800 as cover_path_800,ph.c320 as cover_path_320
from public.dir_listings l
join public.dir_listing_property pr on pr.listing_id=l.id
left join public.dir_places p on p.id=l.place_id
left join public.dir_listing_sellers s on s.profile_id=l.seller_profile_id
cross join lateral public.dir_listing_fuzz(l.id,l.lat,l.lng) f
cross join lateral (select count(*)::integer n,(array_agg(m.path_800 order by m.sort))[1] c800,(array_agg(m.path_320 order by m.sort))[1] c320
 from public.dir_listing_media m where m.listing_id=l.id and m.status='active') ph
where l.vertical='inmuebles' and l.status in('published','reserved') and l.moderation_status in('clear','approved') and l.expires_at>now();

-- Public photos (ordered) and declared financing of a listing (helpers of dir_listing_public).
create or replace function public.dir_listing_public_photos(p_id uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('path1600',m.path_1600,'path800',m.path_800,'path320',m.path_320,'width',m.width,'height',m.height,
  'altEs',m.alt_es,'altEn',m.alt_en) order by m.sort),'[]') from public.dir_listing_media m where m.listing_id=p_id and m.status='active' $$;
-- Only for vehicle listings that opted in (seller_financing), linked to a published dealer place with an active
-- declaration younger than financing_max_age_days. Always marked declaredBySeller (ContrataCR does not verify it).
create or replace function public.dir_listing_public_financing(p_id uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('annualRatePct',f.annual_rate_pct,'maxTermMonths',f.max_term_months,'minDownPaymentPct',f.min_down_payment_pct,
  'declaredAt',f.declared_at,'declaredBySeller',true,'labelEs','Declarada por el vendedor; ContrataCR no la comprueba.','labelEn','Declared by the seller; not checked by ContrataCR.')
 from public.dir_listings l join public.dir_listing_vehicle v on v.listing_id=l.id and v.seller_financing
 join public.dir_places p on p.id=l.place_id and p.status='published'
 join public.dir_listing_financing f on f.place_id=l.place_id and f.status='active'
  and f.declared_at>clock_timestamp()-make_interval(days=>public.dir_listing_limit('financing_max_age_days'))
 where l.id=p_id and l.vertical='vehiculos' $$;

-- Detail by public code (either vertical); null when not public. Adds photos[] and financing (or null).
create or replace function public.dir_listing_public(p_code text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare base jsonb;lid uuid;
begin
 if p_code is null or p_code!~'^[2-9a-hjkmnp-z]{6}$' then return null;end if;
 base:=coalesce(
  (select to_jsonb(v)||jsonb_build_object('vertical','vehiculos') from public.public_vehicle_listings v where v.code=p_code),
  (select to_jsonb(v)||jsonb_build_object('vertical','inmuebles') from public.public_property_listings v where v.code=p_code));
 if base is null then return null;end if;
 select id into lid from public.dir_listings where public_code=p_code;
 return base||jsonb_build_object('photos',public.dir_listing_public_photos(lid),'financing',public.dir_listing_public_financing(lid));
end $$;

-- ---------------------------------------------------------------- privileges
do $$declare n text;begin foreach n in array array['dir_fx_rates','dir_listing_limits','dir_listing_sellers','dir_listings','dir_listing_vehicle','dir_listing_property','dir_listing_actions','dir_listing_history',
 'dir_listing_media','dir_listing_flags','dir_listing_financing'] loop
 execute format('alter table public.%I enable row level security',n);
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',n);
 if n in('dir_listing_actions','dir_listing_history','dir_listing_flags') then execute format('grant select,insert on public.%I to service_role',n);
 else execute format('grant select,insert,update on public.%I to service_role',n);end if;
end loop;
foreach n in array array['public_vehicle_listings','public_property_listings'] loop
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',n);
 execute format('grant select on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and (p.proname like 'dir\_listing\_%' or p.proname like 'dir\_fx\_%') loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  execute format('grant execute on function %s to service_role',f);
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== dir-listing-photos-bucket-local.sql =====
-- LOCAL PRO ONLY (multivertical V3 wiring, 2026-11-16): private Storage bucket for directory listing photos.
-- Depends on directory-listings-local.sql (dir_listing_media rows reference these object keys:
-- dir-listings/<photo id>/<1600|800|320>.webp). Private like every Pro bucket: only the service role reads or writes;
-- the public reader (pending) must check that the photo belongs to a public listing before serving it.
-- Idempotent; skipped where Storage is not installed (PGlite).
do $$
begin
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
   values('dir-listing-photos','dir-listing-photos',false,20971520,array['image/webp','image/jpeg'])
   on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
 end if;
end $$;

-- ===== pro-editions-local.sql =====
-- LOCAL PRO ONLY (multivertical F4, 2026-11-16). Pro editions and modules. Never applied to remote projects.
-- * pro_workspace_editions: one row per owner (edition servicios|autos|restaurantes|bienes_raices|comercio,
--   tier basico|pro|plus, source launch_free|admin|billing, active, revision). No row = implicit servicios/basico.
-- * pro_edition_default_modules(edition): IMMUTABLE table of the modules of each edition and their minimum tier
--   (mirrored in src/lib/pro/editions.ts; the PGlite test compares both).
-- * pro_workspace_modules: per-owner overrides (owner may switch an edition module off/on; admin/billing may lock
--   a module off or add an out-of-edition module).
-- * pro_billing_switches: singleton paywall_enabled (default FALSE = Pro free at launch). Only a platform admin
--   changes it, through pro_billing_switch_set (CAS + actionId). Every change is kept in an immutable history.
--   While paywall_enabled=false every module of the edition is active regardless of tier.
-- * pro_has_module(owner,module) / pro_module_require(actor,owner,module) -> 42501 hint 'module_disabled'.
-- * pro_workspace_edition_mutate(actor,input): CAS revision (40001) + idempotent actionId receipts.
-- * pro_editions_backfill_servicios(admin,dryRun,tier): servicios edition for existing owners. NOT auto-run.
-- * pro_route_module(path): module of NEW vertical /api/pro routes (existing routes -> null, never gated).
-- Depends on: profiles, pro_memberships, pro_workspaces (memberships-draft.sql); pro_role_of / pro_role_require
-- (team-roles-local.sql); pro_entitled / pro_entitled_require (pro-entitled-draft.sql).
-- Independent of the public directory: nothing here reads or writes directory tables, search or ordering.
-- Patterns: RLS on, service_role-only grants, security invoker + fixed search_path, immutable history.
begin;

create table if not exists public.pro_workspace_editions(
 owner_id uuid primary key references public.profiles(id) on delete cascade,
 edition text not null check(edition in('servicios','autos','restaurantes','bienes_raices','comercio')),
 tier text not null default 'basico' check(tier in('basico','pro','plus')),
 source text not null default 'launch_free' check(source in('launch_free','admin','billing')),
 active boolean not null default true,
 revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create table if not exists public.pro_workspace_modules(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 module text not null check(module ~ '^[a-z][a-z_]{1,39}$'),
 enabled boolean not null,
 source text not null check(source in('owner','admin','billing')),
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default now(),
 primary key(owner_id,module));

create table if not exists public.pro_billing_switches(
 id boolean primary key default true check(id),
 paywall_enabled boolean not null default false,
 revision integer not null default 1 check(revision>0),
 updated_by uuid,updated_at timestamptz not null default now());

create table if not exists public.pro_billing_switch_events(
 id uuid primary key default gen_random_uuid(),
 actor_id uuid not null,action_id uuid not null,
 before_enabled boolean not null,after_enabled boolean not null,revision integer not null,
 reason text not null check(length(reason) between 3 and 500),
 at timestamptz not null default now(),unique(actor_id,action_id));

create table if not exists public.pro_workspace_edition_events(
 id uuid primary key default gen_random_uuid(),
 owner_id uuid not null references public.profiles(id) on delete cascade,
 actor_id uuid not null,action_id uuid not null,
 action text not null check(action in('choose_edition','admin_set_edition','set_module','admin_set_module','backfill')),
 module text,before_state jsonb,after_state jsonb not null,reason text not null default '',
 at timestamptz not null default now());
create index if not exists pro_workspace_edition_events_owner_idx on public.pro_workspace_edition_events(owner_id,at desc);

create table if not exists public.pro_edition_actions(
 actor_id uuid not null,action_id uuid not null,
 input_hash text not null check(input_hash~'^[a-f0-9]{32}$'),result jsonb not null,
 at timestamptz not null default now(),primary key(actor_id,action_id));

-- Singleton seed: paywall OFF. Re-applying the module never changes an existing value.
insert into public.pro_billing_switches(id,paywall_enabled) values(true,false) on conflict(id) do nothing;

-- ── Catalogue (immutable) ──────────────────────────────────────────────────────────────────────
create or replace function public.pro_tier_rank(p_tier text) returns integer
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_tier when 'basico' then 1 when 'pro' then 2 when 'plus' then 3 end $$;

create or replace function public.pro_edition_default_modules(p_edition text) returns table(module text,min_tier text)
language sql immutable security invoker set search_path=public,pg_temp as $$
 select d.module,d.min_tier from (
  select e.edition,c.module,c.min_tier,c.o from unnest(array['servicios','autos','restaurantes','bienes_raices','comercio']) e(edition)
   cross join (values('clients','basico',1),('leads','basico',2),('quotes','basico',3),('agenda','basico',4),('payments','basico',5),
    ('catalog','basico',6),('site','basico',7),('statistics','pro',8),('expenses','pro',9),('team','pro',10),
    ('marketing','plus',11),('ai_plus','plus',12)) c(module,min_tier,o)
  union all select v.edition,v.module,v.min_tier,v.o from (values
   ('servicios','projects','basico',20),('servicios','tasks','basico',21),('servicios','timesheets','pro',22),
   ('servicios','visit_prep','pro',23),('servicios','invoice_drafts','pro',24),('servicios','bids','plus',25),
   ('autos','auto_inventory','basico',20),('autos','listings','basico',21),('autos','test_drives','basico',22),
   ('autos','auto_finance_calc','pro',23),('autos','listing_metrics','plus',24),
   ('restaurantes','menu','basico',20),('restaurantes','table_reservations','pro',21),('restaurantes','menu_from_photo','plus',22),
   ('bienes_raices','property_inventory','basico',20),('bienes_raices','listings','basico',21),('bienes_raices','property_visits','basico',22),
   ('bienes_raices','listing_metrics','plus',23),
   ('comercio','inventory','basico',20),('comercio','price_list','basico',21),('comercio','stock_alerts','pro',22)
  ) v(edition,module,min_tier,o)) d
 where d.edition=p_edition order by d.o $$;

create or replace function public.pro_module_catalog() returns setof text
language sql immutable security invoker set search_path=public,pg_temp as $$
 select distinct d.module from unnest(array['servicios','autos','restaurantes','bienes_raices','comercio']) e
  cross join lateral public.pro_edition_default_modules(e) d order by 1 $$;

-- Module of a NEW vertical /api/pro route. Existing routes return null and are never module-gated.
create or replace function public.pro_route_module(p_path text) returns text
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case
  when s ~ '^auto-inventory$' then 'auto_inventory'
  when s ~ '^(auto-listings|listings)$' then 'listings'
  when s ~ '^test-drives$' then 'test_drives'
  when s ~ '^auto-finance$' then 'auto_finance_calc'
  when s ~ '^listing-metrics$' then 'listing_metrics'
  when s ~ '^menu(-items|-sections)?$' then 'menu'
  when s ~ '^menu-from-photo$' then 'menu_from_photo'
  when s ~ '^table-reservations$' then 'table_reservations'
  when s ~ '^property-inventory$' then 'property_inventory'
  when s ~ '^property-visits$' then 'property_visits'
  when s ~ '^(inventory|inventory-items|inventory-movements)$' then 'inventory'
  when s ~ '^(price-list|prices)$' then 'price_list'
  when s ~ '^stock-alerts$' then 'stock_alerts'
  else null end
 from (select split_part(regexp_replace(coalesce(p_path,''),'^/api/pro/?',''),'/',1) s) x $$;

-- ── Effective state ────────────────────────────────────────────────────────────────────────────
create or replace function public.pro_paywall_enabled() returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select paywall_enabled from public.pro_billing_switches where id),false) $$;

-- True when the owner's workspace has the module. Rules (same order in editions.ts hasModule):
-- owner not entitled to Pro -> false; edition row inactive -> false; override enabled=false -> false;
-- module of the edition: paywall off -> true, paywall on -> tier >= min_tier or an admin/billing grant;
-- module outside the edition: only an enabled admin/billing grant (add-on).
create or replace function public.pro_has_module(p_owner uuid,p_module text) returns boolean
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ed text;t text;act boolean;ov public.pro_workspace_modules;has_ov boolean;minimum text;
begin
 if p_owner is null or p_module is null or not public.pro_entitled(p_owner) then return false;end if;
 select e.edition,e.tier,e.active into ed,t,act from public.pro_workspace_editions e where e.owner_id=p_owner;
 if not found then ed:='servicios';t:='basico';act:=true;end if;
 if not act then return false;end if;
 select * into ov from public.pro_workspace_modules m where m.owner_id=p_owner and m.module=p_module;has_ov:=found;
 if has_ov and not ov.enabled then return false;end if;
 select d.min_tier into minimum from public.pro_edition_default_modules(ed) d where d.module=p_module;
 if minimum is null then return has_ov and ov.enabled and ov.source in('admin','billing');end if;
 if not public.pro_paywall_enabled() then return true;end if;
 return public.pro_tier_rank(t)>=public.pro_tier_rank(minimum) or (has_ov and ov.enabled and ov.source in('admin','billing'));
end $$;

-- THE module helper: the actor must work in the owner's company (any role) and the module must be active.
create or replace function public.pro_module_require(p_actor uuid,p_owner uuid,p_module text) returns text
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if p_module is null or not exists(select 1 from public.pro_module_catalog() c where c=p_module) then raise exception 'Unknown module' using errcode='22023';end if;
 if public.pro_role_of(p_actor,p_owner) is null then raise exception 'Forbidden' using errcode='42501';end if;
 if not public.pro_has_module(p_owner,p_module) then raise exception 'module_disabled' using errcode='42501',hint='module_disabled',detail=p_module;end if;
 return p_module;
end $$;

create or replace function public.pro_billing_switch_read() returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select jsonb_build_object('paywallEnabled',paywall_enabled,'revision',revision,'updatedAt',updated_at) from public.pro_billing_switches where id),
  jsonb_build_object('paywallEnabled',false,'revision',0,'updatedAt',null)) $$;

create or replace function public.pro_workspace_edition_read(p_actor uuid,p_owner uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare e public.pro_workspace_editions;implicit boolean;ed text;mods jsonb;
begin
 perform public.pro_role_require(p_actor,p_owner,'read');
 select * into e from public.pro_workspace_editions where owner_id=p_owner;implicit:=not found;ed:=coalesce(e.edition,'servicios');
 select coalesce(jsonb_agg(jsonb_build_object('module',c.m,'minTier',d.min_tier,'inEdition',d.module is not null,
   'override',case when o.module is null then null else jsonb_build_object('enabled',o.enabled,'source',o.source,'revision',o.revision) end,
   'active',public.pro_has_module(p_owner,c.m)) order by c.m),'[]'::jsonb) into mods
 from public.pro_module_catalog() c(m) left join public.pro_edition_default_modules(ed) d on d.module=c.m
  left join public.pro_workspace_modules o on o.owner_id=p_owner and o.module=c.m;
 return jsonb_build_object('ownerId',p_owner,'edition',ed,'tier',coalesce(e.tier,'basico'),'source',coalesce(e.source,'launch_free'),
  'active',coalesce(e.active,true),'revision',coalesce(e.revision,0),'implicit',implicit,'paywallEnabled',public.pro_paywall_enabled(),
  'entitled',public.pro_entitled(p_owner),'modules',mods);
end $$;

-- ── Mutations ──────────────────────────────────────────────────────────────────────────────────
create or replace function public.pro_edition_is_admin(p_actor uuid) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select exists(select 1 from public.profiles where id=p_actor and role='admin' and not coalesce(is_disabled,false)) $$;

-- Inputs (exact key sets; revision = current row revision, 0 when the row does not exist):
--  choose_edition   {action,actionId,edition,ownerId,revision}                        owner / settings.write
--  set_module       {action,actionId,enabled,module,ownerId,revision}                  owner / settings.write
--  admin_set_edition{action,actionId,active,edition,ownerId,reason,revision,source,tier} platform admin
--  admin_set_module {action,actionId,enabled,module,ownerId,reason,revision,source}    platform admin (source admin|billing)
create or replace function public.pro_workspace_edition_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql volatile security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;own uuid;rev integer;keys text[];hash text;prior public.pro_edition_actions;
 cur public.pro_workspace_editions;has_cur boolean;m public.pro_workspace_modules;has_m boolean;
 ed text;mod text;src text;why text:='';before jsonb;after jsonb;answer jsonb;
begin
 if p_actor is null or p_input is null or jsonb_typeof(p_input)<>'object' then raise exception 'Invalid edition action' using errcode='22023';end if;
 act:=p_input->>'action';
 if act is null or act not in('choose_edition','set_module','admin_set_edition','admin_set_module') or jsonb_typeof(p_input->'actionId') is distinct from 'string'
  or jsonb_typeof(p_input->'ownerId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' then raise exception 'Invalid edition action' using errcode='22023';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if act='choose_edition' and keys<>array['action','actionId','edition','ownerId','revision']
  or act='set_module' and keys<>array['action','actionId','enabled','module','ownerId','revision']
  or act='admin_set_edition' and keys<>array['action','actionId','active','edition','ownerId','reason','revision','source','tier']
  or act='admin_set_module' and keys<>array['action','actionId','enabled','module','ownerId','reason','revision','source'] then raise exception 'Invalid fields' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;own:=(p_input->>'ownerId')::uuid;rev:=(p_input->>'revision')::integer;
 exception when others then raise exception 'Invalid edition action' using errcode='22023';end;
 if rev<0 or (p_input->>'revision')::numeric<>rev then raise exception 'Invalid revision' using errcode='22023';end if;
 hash:=md5(p_input::text);
 perform pg_advisory_xact_lock(hashtextextended('pro-edition-action:'||p_actor::text||':'||aid::text,0));
 select * into prior from public.pro_edition_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;

 if act like 'admin\_%' then
  if not public.pro_edition_is_admin(p_actor) then raise exception 'admin required' using errcode='42501';end if;
  why:=btrim(coalesce(p_input->>'reason',''));
  if length(why) not between 3 and 500 then raise exception 'Reason required' using errcode='22023';end if;
  if not exists(select 1 from public.profiles where id=own) then raise exception 'Owner unavailable' using errcode='P0002';end if;
 else
  perform public.pro_role_require(p_actor,own,'settings.write');
  perform public.pro_entitled_require(own);
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-edition:'||own::text,0));
 select * into cur from public.pro_workspace_editions where owner_id=own for update;has_cur:=found;

 if act in('choose_edition','admin_set_edition') then
  ed:=p_input->>'edition';
  if ed is null or ed not in('servicios','autos','restaurantes','bienes_raices','comercio') then raise exception 'Invalid edition' using errcode='22023';end if;
  if coalesce(cur.revision,0)<>rev then raise exception 'Edition changed' using errcode='40001';end if;
  before:=case when has_cur then jsonb_build_object('edition',cur.edition,'tier',cur.tier,'source',cur.source,'active',cur.active,'revision',cur.revision) end;
  if act='choose_edition' then
   if has_cur and not cur.active then raise exception 'Edition suspended' using errcode='42501',hint='edition_inactive';end if;
   if has_cur then update public.pro_workspace_editions set edition=ed,revision=revision+1,updated_at=now() where owner_id=own returning * into cur;
   else insert into public.pro_workspace_editions(owner_id,edition,tier,source,active) values(own,ed,'basico',case when public.pro_paywall_enabled() then 'billing' else 'launch_free' end,true) returning * into cur;end if;
  else
   if p_input->>'tier' is null or p_input->>'tier' not in('basico','pro','plus') or p_input->>'source' is null or p_input->>'source' not in('launch_free','admin','billing')
    or jsonb_typeof(p_input->'active')<>'boolean' then raise exception 'Invalid edition' using errcode='22023';end if;
   insert into public.pro_workspace_editions(owner_id,edition,tier,source,active) values(own,ed,p_input->>'tier',p_input->>'source',(p_input->>'active')::boolean)
   on conflict(owner_id) do update set edition=excluded.edition,tier=excluded.tier,source=excluded.source,active=excluded.active,
    revision=public.pro_workspace_editions.revision+1,updated_at=now() returning * into cur;
  end if;
  after:=jsonb_build_object('edition',cur.edition,'tier',cur.tier,'source',cur.source,'active',cur.active,'revision',cur.revision);
  answer:=jsonb_build_object('ownerId',own,'action',act)||after;
 else
  mod:=p_input->>'module';
  if mod is null or not exists(select 1 from public.pro_module_catalog() c where c=mod) then raise exception 'Unknown module' using errcode='22023';end if;
  if jsonb_typeof(p_input->'enabled')<>'boolean' then raise exception 'Invalid module' using errcode='22023';end if;
  select * into m from public.pro_workspace_modules where owner_id=own and module=mod for update;has_m:=found;
  if coalesce(m.revision,0)<>rev then raise exception 'Module changed' using errcode='40001';end if;
  if act='set_module' then
   if has_cur and not cur.active then raise exception 'Edition suspended' using errcode='42501',hint='edition_inactive';end if;
   if not exists(select 1 from public.pro_edition_default_modules(coalesce(cur.edition,'servicios')) d where d.module=mod) then raise exception 'Module not in edition' using errcode='22023',hint='module_not_in_edition';end if;
   if has_m and m.source<>'owner' then raise exception 'Module locked' using errcode='42501',hint='module_locked';end if;
   src:='owner';
  else
   src:=p_input->>'source';
   if src is null or src not in('admin','billing') then raise exception 'Invalid source' using errcode='22023';end if;
  end if;
  before:=case when has_m then jsonb_build_object('enabled',m.enabled,'source',m.source,'revision',m.revision) end;
  insert into public.pro_workspace_modules(owner_id,module,enabled,source) values(own,mod,(p_input->>'enabled')::boolean,src)
  on conflict(owner_id,module) do update set enabled=excluded.enabled,source=excluded.source,revision=public.pro_workspace_modules.revision+1,updated_at=now()
  returning * into m;
  after:=jsonb_build_object('enabled',m.enabled,'source',m.source,'revision',m.revision);
  answer:=jsonb_build_object('ownerId',own,'action',act,'module',mod,'active',public.pro_has_module(own,mod))||after;
 end if;
 insert into public.pro_workspace_edition_events(owner_id,actor_id,action_id,action,module,before_state,after_state,reason)
 values(own,p_actor,aid,act,mod,before,after,why);
 insert into public.pro_edition_actions(actor_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer||jsonb_build_object('replayed',false);
end $$;

-- Paywall switch. Input {actionId,paywallEnabled,reason,revision}. Platform admin only.
create or replace function public.pro_billing_switch_set(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql volatile security invoker set search_path=public,pg_temp as $$
declare aid uuid;rev integer;keys text[];hash text;prior public.pro_edition_actions;s public.pro_billing_switches;was boolean;why text;answer jsonb;
begin
 if p_actor is null or p_input is null or jsonb_typeof(p_input)<>'object' then raise exception 'Invalid switch action' using errcode='22023';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if keys<>array['actionId','paywallEnabled','reason','revision'] or jsonb_typeof(p_input->'paywallEnabled')<>'boolean'
  or jsonb_typeof(p_input->'revision')<>'number' or jsonb_typeof(p_input->'actionId')<>'string' then raise exception 'Invalid fields' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;exception when others then raise exception 'Invalid switch action' using errcode='22023';end;
 hash:=md5(p_input::text);
 if not public.pro_edition_is_admin(p_actor) then raise exception 'admin required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-edition-action:'||p_actor::text||':'||aid::text,0));
 select * into prior from public.pro_edition_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 why:=btrim(coalesce(p_input->>'reason',''));
 if length(why) not between 3 and 500 then raise exception 'Reason required' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-billing-switch',0));
 select * into s from public.pro_billing_switches where id for update;
 if not found then raise exception 'Switch unavailable' using errcode='P0002';end if;
 if s.revision<>rev then raise exception 'Switch changed' using errcode='40001';end if;
 was:=s.paywall_enabled;
 perform set_config('pro.billing_switch_write','1',true);
 update public.pro_billing_switches set paywall_enabled=(p_input->>'paywallEnabled')::boolean,revision=revision+1,updated_by=p_actor,updated_at=now() where id returning * into s;
 perform set_config('pro.billing_switch_write','',true);
 insert into public.pro_billing_switch_events(actor_id,action_id,before_enabled,after_enabled,revision,reason) values(p_actor,aid,was,s.paywall_enabled,s.revision,why);
 answer:=jsonb_build_object('paywallEnabled',s.paywall_enabled,'revision',s.revision);
 insert into public.pro_edition_actions(actor_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer||jsonb_build_object('replayed',false);
end $$;

-- Servicios edition for existing Pro owners (any pro_memberships or pro_workspaces row) without an edition.
-- NOT run by this module. Dry run by default; idempotent (never touches existing rows).
create or replace function public.pro_editions_backfill_servicios(p_actor uuid,p_dry_run boolean default true,p_tier text default 'pro') returns jsonb
language plpgsql volatile security invoker set search_path=public,pg_temp as $$
declare total integer;ids uuid[];n integer:=0;o uuid;
begin
 if not public.pro_edition_is_admin(p_actor) then raise exception 'admin required' using errcode='42501';end if;
 if p_dry_run is null or p_tier is null or p_tier not in('basico','pro','plus') then raise exception 'Invalid backfill' using errcode='22023';end if;
 select coalesce(array_agg(p.id order by p.id),'{}') into ids from public.profiles p
  where (exists(select 1 from public.pro_memberships m where m.user_id=p.id) or exists(select 1 from public.pro_workspaces w where w.user_id=p.id))
   and not exists(select 1 from public.pro_workspace_editions e where e.owner_id=p.id);
 total:=coalesce(array_length(ids,1),0);
 if p_dry_run then return jsonb_build_object('dryRun',true,'candidates',total,'inserted',0,'sample',to_jsonb(ids[1:50]));end if;
 foreach o in array ids loop
  insert into public.pro_workspace_editions(owner_id,edition,tier,source,active) values(o,'servicios',p_tier,'launch_free',true) on conflict(owner_id) do nothing;
  if found then n:=n+1;
   insert into public.pro_workspace_edition_events(owner_id,actor_id,action_id,action,after_state,reason)
   values(o,p_actor,md5('pro-edition-backfill:'||o::text)::uuid,'backfill',jsonb_build_object('edition','servicios','tier',p_tier,'source','launch_free','active',true,'revision',1),'servicios backfill');
  end if;
 end loop;
 return jsonb_build_object('dryRun',false,'candidates',total,'inserted',n,'sample',to_jsonb(ids[1:50]));
end $$;

-- ── Immutability, RLS, grants ──────────────────────────────────────────────────────────────────
create or replace function public.pro_edition_history_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 -- Account deletion: the owner's profile is already gone, so the ON DELETE CASCADE of its edition events may proceed
 -- (same rule as the other immutable Pro histories, e.g. work-budget-local.sql). Anything else stays immutable.
 if tg_op='DELETE' and tg_table_name='pro_workspace_edition_events' then
  if not exists(select 1 from public.profiles where id=old.owner_id) then return old;end if;
 end if;
 raise exception 'Immutable edition history' using errcode='23514';
end $$;
create or replace function public.pro_billing_switch_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='UPDATE' and current_setting('pro.billing_switch_write',true)='1' and new.id then return new;end if;
 raise exception 'Billing switch changes only through pro_billing_switch_set' using errcode='23514';
end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_workspace_editions','pro_workspace_modules','pro_billing_switches','pro_billing_switch_events','pro_workspace_edition_events','pro_edition_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);end loop;
 grant select,insert,update on public.pro_workspace_editions,public.pro_workspace_modules to service_role;
 grant select,update on public.pro_billing_switches to service_role;
 grant select,insert on public.pro_billing_switch_events,public.pro_workspace_edition_events,public.pro_edition_actions to service_role;
 foreach t in array array['pro_billing_switch_events','pro_workspace_edition_events','pro_edition_actions'] loop
  execute format('drop trigger if exists pro_edition_history_immutable on public.%I',t);
  execute format('create trigger pro_edition_history_immutable before update or delete on public.%I for each row execute function public.pro_edition_history_immutable()',t);
  execute format('drop trigger if exists pro_edition_history_no_truncate on public.%I',t);
  execute format('create trigger pro_edition_history_no_truncate before truncate on public.%I for each statement execute function public.pro_edition_history_immutable()',t);end loop;
 drop trigger if exists pro_billing_switch_guard on public.pro_billing_switches;
 create trigger pro_billing_switch_guard before update or delete on public.pro_billing_switches for each row execute function public.pro_billing_switch_guard();
 drop trigger if exists pro_billing_switch_no_truncate on public.pro_billing_switches;
 create trigger pro_billing_switch_no_truncate before truncate on public.pro_billing_switches for each statement execute function public.pro_edition_history_immutable();
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_tier_rank','pro_edition_default_modules','pro_module_catalog','pro_route_module','pro_paywall_enabled','pro_has_module','pro_module_require','pro_billing_switch_read','pro_workspace_edition_read','pro_edition_is_admin','pro_workspace_edition_mutate','pro_billing_switch_set','pro_editions_backfill_servicios','pro_edition_history_immutable','pro_billing_switch_guard') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== pro-editions-team-gate-local.sql =====
-- LOCAL PRO ONLY (multivertical F4 wiring, 2026-11-16). Team-roles gate for Pro editions/modules.
-- Depends on: team-roles-local.sql (pro_role_of, pro_company_team_activity, pro_team_name, grants) and
--             pro-editions-local.sql (pro_route_module, pro_has_module).
-- Applied AFTER both so team-roles-local.sql stays untouched (no dependency cycle).
-- * New capabilities: inventory.write, listing.publish, price.write, menu.write (public-facing publish/price only for
--   admin/manager; members may edit inventory and menu; read_only stays read).
-- * pro_team_route_authorize checks the role first, then the module of the route (a GET to a disabled module is
--   also refused with reason module_disabled).
-- Idempotent: only create or replace; create or replace keeps the existing grants.
begin;
create or replace function public.pro_role_allows(p_role text,p_capability text) returns boolean
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_role
  when 'admin' then p_capability in('read','work.write','lead.write','sales.write','finance.write','company.write','settings.write','team.manage','inventory.write','listing.publish','price.write','menu.write')
  when 'manager' then p_capability in('read','work.write','lead.write','sales.write','finance.write','company.write','inventory.write','listing.publish','price.write','menu.write')
  when 'member' then p_capability in('read','work.write','lead.write','inventory.write','menu.write')
  when 'read_only' then p_capability='read'
  else false end
$$;
create or replace function public.pro_role_matrix_read() returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_object_agg(r,(select jsonb_agg(c order by o) from unnest(array['read','work.write','lead.write','sales.write','finance.write','company.write','settings.write','team.manage','inventory.write','listing.publish','price.write','menu.write']) with ordinality x(c,o) where public.pro_role_allows(r,c)))
 from unnest(array['admin','manager','member','read_only']) r
$$;
create or replace function public.pro_role_require(p_actor uuid,p_owner uuid,p_capability text) returns text
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r text;
begin
 if p_capability is null or p_capability not in('read','work.write','lead.write','sales.write','finance.write','company.write','settings.write','team.manage','inventory.write','listing.publish','price.write','menu.write') then raise exception 'Unknown capability' using errcode='22023';end if;
 r:=public.pro_role_of(p_actor,p_owner);
 if r is null or not public.pro_role_allows(r,p_capability) then raise exception 'Role does not allow %',p_capability using errcode='42501';end if;
 return r;
end $$;
create or replace function public.pro_role_route_capability(p_method text,p_path text) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare seg text:=split_part(regexp_replace(coalesce(p_path,''),'^/api/pro/?',''),'/',1);
begin
 if upper(coalesce(p_method,'')) in('GET','HEAD','OPTIONS') then return 'read';end if;
 if seg in('team','team-roles') then return 'team.manage';end if;
 if seg ~ '^(auto-inventory|property-inventory|inventory|inventory-items|inventory-movements|stock-alerts)$' then return 'inventory.write';end if;
 if seg ~ '^(auto-listings|listings)$' then return 'listing.publish';end if;
 if seg ~ '^(price-list|prices)$' then return 'price.write';end if;
 if seg ~ '^(menu|menu-items|menu-sections|menu-from-photo)$' then return 'menu.write';end if;
 if seg ~ '^(integrations|connectors|oauth|site|site-public|marketing|marketing-confirm|ads-tracking|social|social-content|promotions|invoice-document-settings|invoice-issuer|accounting|accounting-export|einvoice|einvoice-file)$' then return 'settings.write';end if;
 if seg ~ '^(invoice-|payment-|pay$|client-operations|client-balance|client-statement|client-finances|credits-retainers|work-billing|work-budget|work-costs|expenses|expense-receipts|purchase-order|online-payments)' then return 'finance.write';end if;
 if seg ~ '^(lead-|request-pipeline|request-followups|manual-lead-)' then return 'lead.write';end if;
 if seg ~ '^(private-estimate|quote|quotes|contract|esign|appointment-|reservations|bids|bid-portal-links|work-changes|selections|allowances|project-quote-context|visit-preparation|work-client-invitations|client-dashboard|client-pending|client-fiscal|request-quotes|direct-project|workspace|projects|work-header|identity-lookup)' then return 'sales.write';end if;
 if seg ~ '^(catalog|company-|service-packages|discount-presets|task-templates|schedule-templates|ai|ai-meetings)' then return 'company.write';end if;
 return 'work.write';
end $$;
create or replace function public.pro_team_workspace_resolve(p_member uuid,p_owner uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r text;
begin
 if p_member is null or p_owner is null or p_member=p_owner then return null;end if;
 r:=public.pro_role_of(p_member,p_owner);
 if r is null or not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then return null;end if;
 return jsonb_build_object('ownerId',p_owner,'ownerName',coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=p_owner),public.pro_team_name(p_owner)),
  'role',r,'capabilities',(select jsonb_agg(c) from unnest(array['read','work.write','lead.write','sales.write','finance.write','company.write','settings.write','team.manage','inventory.write','listing.publish','price.write','menu.write']) c where public.pro_role_allows(r,c)));
end $$;
create or replace function public.pro_team_route_authorize(p_member uuid,p_owner uuid,p_method text,p_path text) returns jsonb
language plpgsql volatile security invoker set search_path=public,pg_temp as $$
declare ws jsonb;cap text;mod text;
begin
 if p_path is null or length(p_path)>200 or p_path !~ '^/api/pro(/|$)' then raise exception 'Invalid route' using errcode='22023';end if;
 ws:=public.pro_team_workspace_resolve(p_member,p_owner);
 if ws is null then return jsonb_build_object('allowed',false,'reason','not_member');end if;
 cap:=public.pro_role_route_capability(p_method,p_path);
 begin perform public.pro_role_require(p_member,p_owner,cap);
 exception when insufficient_privilege then return jsonb_build_object('allowed',false,'reason','role','role',ws->>'role','capability',cap);end;
 mod:=public.pro_route_module(p_path);
 if mod is not null and not public.pro_has_module(p_owner,mod) then
  return jsonb_build_object('allowed',false,'reason','module_disabled','role',ws->>'role','capability',cap,'module',mod);end if;
 if cap<>'read' then
  insert into public.pro_company_team_activity(owner_id,member_user_id,member_name,role,capability,method,path)
  values(p_owner,p_member,public.pro_team_name(p_member),ws->>'role',cap,upper(p_method),left(p_path,200));
 end if;
 return jsonb_build_object('allowed',true,'role',ws->>'role','capability',cap);
end $$;
commit;

-- ===== pro-work-activity-local.sql =====
-- LOCAL PRO ONLY (2026-11-17). Per-job «Actividad» / «Activity» history.
-- One read-only RPC. No table, column, trigger or row is created or changed: every event is read from the
-- append-only history / event / receipt records the job modules already keep:
--   quote_*            pro_private_estimate_publication_events (immutable trigger) + pro_private_estimate_publications
--                      (immutable content: title, version) of the quotes that belong to the job (pro_project_estimate_rows)
--   change_*           pro_work_change_actions (receipt per action) + pro_work_changes (a decided change is final:
--                      only a 'proposed' row can change, so the decision time updated_at never moves again)
--   payment_*          pro_client_entries kind payment / payment_void (append-only ledger; a void is a new entry)
--   invoice_prepared   pro_invoice_billing_requests (creation receipt of a job invoice draft)
--   invoice_payment_*  pro_invoice_payment_applications / pro_invoice_payment_voids (immutable trigger)
--   einvoice_*         pro_einvoice_events (immutable trigger) of the job's invoice drafts
--   file_added         pro_work_file_upload_actions confirmed receipts (immutable after confirmation)
--   file_shared        pro_work_file_publish_actions (immutable trigger)
--   file_trashed/_restored  pro_work_file_organizer_history
--   task_*             pro_work_task_history (immutable trigger) + pro_work_task_actions (actor)
--   daily_log_published pro_daily_log_history action 'publish'
--   update_published   pro_work_update_history action 'publish'
--   client_invited / client_invitation_accepted  pro_work_client_invitations (created_at / accepted_at are frozen
--                      by pro_work_client_invitation_guard)
-- Not sourced: the job's own stage/status (pro_work.stage is a current value without a history record).
-- Authorization: the owner, or an active company member whose role allows 'read' (pro_role_require). The owner
-- must have Pro work tools. A job that is not the owner's is refused with 42501 (never a partial result).
-- Free text written by other people (change notes, quote change requests, file comments) is never returned;
-- titles are the owner's own record names and are rendered as plain text by the UI.
-- Ordering: newest first by (at, id); keyset cursor (p_before_at, p_before_id), at most 50 per page.
begin;
create or replace function public.pro_work_activity_read(p_actor uuid,p_owner uuid,p_work text,p_before_at timestamptz default null,p_before_id text default null,p_limit integer default 20) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;lim integer:=coalesce(p_limit,20);result jsonb;
begin
 if p_actor is null or p_owner is null or not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_actor<>p_owner then perform public.pro_role_require(p_actor,p_owner,'read');end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or lim not between 1 and 50 or (p_before_at is null)<>(p_before_id is null) or length(p_before_id)>120 then raise exception 'Invalid activity query' using errcode='22023';end if;
 select * into w from public.pro_work where user_id=p_owner and id=p_work;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 with ev(id,at,kind,actor,actor_name,section,ref,data) as(
  -- Quotes of this job: shared, claimed, accepted, declined, changes requested / answered, withdrawn.
  select 'quote:'||e.publication_id||':'||e.revision,e.at,'quote_'||e.action,e.actor_id,null::text,'estimates',
   jsonb_build_object('estimateId',v.estimate_id,'publicationId',v.id),jsonb_build_object('title',left(v.content->>'title',160),'version',v.version)
  from public.pro_private_estimate_publication_events e join public.pro_private_estimate_publications v on v.id=e.publication_id
  where v.owner_id=p_owner and e.action in('publish','claim','accept','decline','request_changes','respond_changes','withdraw')
   and v.estimate_id in(select r.estimate_id from public.pro_project_estimate_rows(p_owner,w) r where r.relation='project')
  union all
  -- Change orders: proposed, accepted (by the customer or recorded by the owner), declined, withdrawn.
  select 'change:'||a.id,case when a.input->>'action'='propose' then c.created_at else c.updated_at end,'change_'||(a.input->>'action'),a.actor_id,null,'changes',
   jsonb_build_object('changeId',c.id),jsonb_build_object('title',c.reason,'amountCents',c.delta_cents)
  from public.pro_work_change_actions a join public.pro_work_changes c on c.owner_id=a.owner_id and c.id=(a.result->>'id')::uuid
  where a.owner_id=p_owner and c.work_id=w.id and a.input->>'action' in('propose','accept','decline','withdraw','record_acceptance')
  union all
  -- Payments recorded on the job's customer account (and their voids).
  select 'entry:'||x.id,x.created_at,case x.kind when 'payment' then 'payment_recorded' else 'payment_voided' end,null::uuid,null,'costs',
   jsonb_build_object('entryId',x.id),jsonb_build_object('amountCents',x.amount_cents)
  from public.pro_client_entries x where x.user_id=p_owner and x.work_id=w.id and x.kind in('payment','payment_void')
  union all
  -- Invoice drafts prepared from the job.
  select 'invoice:'||r.request_id,r.created_at,'invoice_prepared',null::uuid,null,'costs',
   jsonb_build_object('invoiceId',d.id),jsonb_build_object('title',d.title)
  from public.pro_invoice_billing_requests r join public.pro_invoice_drafts d on d.user_id=r.user_id and d.id=r.draft_id
  where r.user_id=p_owner and d.work_id=w.id
  union all
  -- Payments applied to (and removed from) the job's invoices.
  select 'invoice-payment:'||pa.id,pa.created_at,'invoice_payment_applied',null::uuid,null,'costs',
   jsonb_build_object('invoiceId',d.id),jsonb_build_object('title',d.title,'amountCents',pa.amount_cents)
  from public.pro_invoice_payment_applications pa join public.pro_invoice_drafts d on d.user_id=pa.user_id and d.id=pa.draft_id
  where pa.user_id=p_owner and d.work_id=w.id
  union all
  select 'invoice-payment-void:'||pv.id,pv.created_at,'invoice_payment_voided',null::uuid,null,'costs',
   jsonb_build_object('invoiceId',d.id),jsonb_build_object('title',d.title,'amountCents',pa.amount_cents)
  from public.pro_invoice_payment_voids pv join public.pro_invoice_payment_applications pa on pa.user_id=pv.user_id and pa.id=pv.application_id
   join public.pro_invoice_drafts d on d.user_id=pa.user_id and d.id=pa.draft_id
  where pv.user_id=p_owner and d.work_id=w.id
  union all
  -- Electronic invoice status transitions of the job's invoices (no draft 'borrador' noise).
  select 'einvoice:'||ee.document_id||':'||ee.id,ee.created_at,case ee.to_status when 'firmado' then 'einvoice_signed' when 'enviado' then 'einvoice_sent' when 'aceptado' then 'einvoice_accepted' else 'einvoice_rejected' end,null::uuid,null,'costs',
   jsonb_build_object('invoiceId',d.id),jsonb_build_object('title',d.title,'number',doc.consecutivo)
  from public.pro_einvoice_events ee join public.pro_einvoice_documents doc on doc.owner_id=ee.owner_id and doc.id=ee.document_id
   join public.pro_invoice_drafts d on d.user_id=doc.owner_id and d.id=doc.draft_id
  where ee.owner_id=p_owner and d.work_id=w.id and ee.to_status in('firmado','enviado','aceptado','rechazado')
  union all
  -- Files: confirmed uploads, shares with the customer, trash and restore.
  select 'file:'||u.file_id,u.at,'file_added',u.actor_id,null,'files',jsonb_build_object('fileId',f.id),jsonb_build_object('title',f.name)
  from public.pro_work_file_upload_actions u join public.pro_work_files f on f.id=u.file_id
  where f.owner_id=p_owner and f.work_id=w.id and u.result is not null
  union all
  select 'file-share:'||pu.action_id,pu.at,'file_shared',pu.actor_id,null,'files',jsonb_build_object('fileId',f.id),jsonb_build_object('title',f.name)
  from public.pro_work_file_publish_actions pu join public.pro_work_files f on f.id=(pu.input->>'fileId')::uuid
  where pu.actor_id=p_owner and f.owner_id=p_owner and f.work_id=w.id
  union all
  select 'file-organizer:'||h.action_id,h.at,case h.action when 'trash_file' then 'file_trashed' else 'file_restored' end,p_owner,null,'files',
   jsonb_build_object('fileId',f.id),jsonb_build_object('title',f.name)
  from public.pro_work_file_organizer_history h join public.pro_work_files f on f.owner_id=h.owner_id and f.id=h.subject_id
  where h.owner_id=p_owner and h.subject='file' and h.action in('trash_file','restore_file') and f.work_id=w.id
  union all
  -- Tasks: created, completed, reopened, archived.
  select 'task:'||t.action_id,t.at,case t.action when 'create' then 'task_created' when 'complete' then 'task_completed' when 'reopen' then 'task_reopened' else 'task_archived' end,
   (select ta.actor_id from public.pro_work_task_actions ta where ta.action_id=t.action_id limit 1),null,'tasks',
   jsonb_build_object('taskId',t.task_id),jsonb_build_object('title',left(t.after_task->>'title',160))
  from public.pro_work_task_history t where t.owner_id=p_owner and t.work_id=w.id and t.action in('create','complete','reopen','archive')
  union all
  -- Daily logs and job updates published.
  select 'daily-log:'||l.action_id,l.at,'daily_log_published',l.actor_id,l.actor_name,'updates',
   jsonb_build_object('logId',l.log_id),jsonb_build_object('title',left(l.after_log->>'title',160))
  from public.pro_daily_log_history l where l.owner_id=p_owner and l.work_id=w.id and l.action='publish'
  union all
  select 'update:'||uh.action_id,uh.at,'update_published',p_owner,null,'updates',
   jsonb_build_object('updateId',uh.entry_id),jsonb_build_object('title',left(uh.after_entry->>'title',160))
  from public.pro_work_update_history uh where uh.owner_id=p_owner and uh.work_id=w.id and uh.action='publish'
  union all
  -- Customer invitations: created and accepted.
  select 'invite:'||i.id,i.created_at,'client_invited',p_owner,null,'client',jsonb_build_object('invitationId',i.id),'{}'::jsonb
  from public.pro_work_client_invitations i where i.owner_id=p_owner and i.work_id=w.id
  union all
  select 'invite-accepted:'||i.id,i.accepted_at,'client_invitation_accepted',i.accepted_by,null,'client',jsonb_build_object('invitationId',i.id),'{}'::jsonb
  from public.pro_work_client_invitations i where i.owner_id=p_owner and i.work_id=w.id and i.accepted_at is not null
 ),page as(
  select * from ev where p_before_at is null or (ev.at,ev.id)<(p_before_at,p_before_id) order by ev.at desc,ev.id desc limit lim+1
 ),shown as(
  select p.*,row_number() over(order by p.at desc,p.id desc) n from page p
 )
 select jsonb_build_object('workId',w.id,
  'items',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'kind',s.kind,
    'at',to_char(s.at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'actorName',nullif(left(btrim(coalesce(s.actor_name,case when s.actor is null then public.pro_team_name(p_owner) else public.pro_team_name(s.actor) end)),160),''),
    'actorRole',case when s.actor is null or s.actor=p_owner then 'owner' when exists(select 1 from public.pro_company_members m where m.owner_id=p_owner and m.member_user_id=s.actor) then 'team' else 'client' end,
    'section',s.section,'ref',s.ref,'data',jsonb_strip_nulls(s.data)) order by s.at desc,s.id desc) from shown s where s.n<=lim),'[]'::jsonb),
  'nextCursor',(select jsonb_build_object('before',to_char(s.at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'beforeId',s.id) from shown s where s.n=lim and exists(select 1 from shown x where x.n>lim))
 ) into result;
 return result;
end $$;
revoke all on function public.pro_work_activity_read(uuid,uuid,text,timestamptz,text,integer) from public,anon,authenticated;
grant execute on function public.pro_work_activity_read(uuid,uuid,text,timestamptz,text,integer) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== payables-cashflow-local.sql =====
-- LOCAL PRO ONLY (2026-11-19, round F1-A, parity register row 55). Accounts payable, cash flow and a simple
-- income statement for the owner. MANAGEMENT REPORTS: no tax filing, no ledger, no bank operation, nothing is sent,
-- charged or moved. CRC cents (the expense/PO model is CRC only), Costa Rica calendar days.
--
-- Accounts payable reuse what already exists (no duplicated amounts, suppliers or payments):
--   * Expenses (pro_internal_expenses) ARE supplier bills already: supplier, date, due date, amount and their own
--     payments/reversals (pro_expense_payments). Every expense is a payable.
--   * A purchase order (pro_purchase_orders, issued/partial/received) becomes a payable when the owner records the
--     supplier's bill for it: bill number, bill date and due date. Amount and payments stay the PO's own
--     (pro_purchase_order_figures, pro_purchase_order_payments). One bill per order.
--   * pro_payable_bills only keeps what did not exist: bill number, bill/due date of a PO bill, a note and the
--     «anulada» state (with reason) of either source. A bill with payments cannot be voided (reverse them first).
--   * Payments made: the «pay» action validates the bill and DELEGATES to the existing writers
--     (pro_expense_meta_save 'payment' / pro_purchase_orders_mutate 'pay'), with the same actionId, so balances,
--     receipts and histories stay in the source module. Reversals stay in Expenses / Purchase orders.
--   * Status: pendiente (nothing paid), parcial, pagada (balance 0), anulada; overdue = open and due before today.
--   * Aging 0-30/31-60/61-90/90+ by supplier: open balance by days since the bill/expense date (same rule as the
--     receivables aging of pro_reports_finance_read), plus the overdue amount.
-- Cash flow (pro_cash_flow_read): per week (Monday) or month of a chosen period.
--   In, actual: payments received (pro_invoice_payments, reversed ones left out: same «collected» as the reports).
--   In, expected: open invoice-draft balances (pro_report_draft_open) due on planned date (or creation day) + credit
--     days; open payment-plan installments (pro_payment_plan_state). Drafts that bill an installment are left out so
--     the installment is counted once.
--   Out, actual: expense payments and PO payments (a reversal is negative on its own day) and customer refunds.
--   Out, expected: open payables by due date.
--   Expected money cannot arrive in the past: an overdue item is placed on today (flagged overdue).
-- Income statement (pro_income_statement_read): income = invoice drafts (not archived) without IVA by creation day;
--   collected shown apart (cash basis, informational). Costs = expenses without IVA when the rate is known (by
--   expense date, per category; voided ones left out) + internal cost of recorded hours (pro_work_cost_entries
--   time − time_void) + PO supplier bills without tax (bill date; voided/cancelled left out). Per period and per job.
-- Patterns: RLS on, service_role only, security invoker, pinned search_path, receipts by actionId, CAS revision,
-- immutable history. Reapplicable.
begin;

create table if not exists public.pro_payable_bills(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null default gen_random_uuid(),
 source_kind text not null check(source_kind in('purchase_order','expense')),
 purchase_order_id uuid,expense_id uuid,
 bill_number text check(bill_number is null or length(btrim(bill_number)) between 1 and 60),
 bill_date date check(bill_date is null or bill_date between date '2000-01-01' and date '2100-12-31'),
 due_date date check(due_date is null or due_date between date '2000-01-01' and date '2100-12-31'),
 note text check(note is null or length(btrim(note)) between 1 and 300),
 voided_at timestamptz,
 void_reason text check(void_reason is null or length(btrim(void_reason)) between 1 and 300),
 revision integer not null default 1 check(revision between 1 and 2147483646),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),
 foreign key(owner_id,purchase_order_id) references public.pro_purchase_orders(owner_id,id) on delete cascade,
 foreign key(owner_id,expense_id) references public.pro_internal_expenses(user_id,id) on delete cascade,
 check((source_kind='purchase_order' and purchase_order_id is not null and expense_id is null and bill_date is not null)
  or (source_kind='expense' and expense_id is not null and purchase_order_id is null and bill_date is null and due_date is null)),
 check(due_date is null or bill_date is null or due_date>=bill_date),
 check((voided_at is null)=(void_reason is null))
);
create unique index if not exists pro_payable_bills_po on public.pro_payable_bills(owner_id,purchase_order_id) where purchase_order_id is not null;
create unique index if not exists pro_payable_bills_expense on public.pro_payable_bills(owner_id,expense_id) where expense_id is not null;
create table if not exists public.pro_payable_bill_history(
 owner_id uuid not null,bill_id uuid not null,action_id uuid not null,
 action text not null check(action in('save','void','restore')),
 before_value jsonb,after_value jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,action_id),
 foreign key(owner_id,bill_id) references public.pro_payable_bills(owner_id,id) on delete cascade
);
create index if not exists pro_payable_bill_history_page on public.pro_payable_bill_history(owner_id,bill_id,at desc);
create table if not exists public.pro_payable_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id)
);

create or replace function public.pro_payable_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Payable bill history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_payable_bill_history_immutable on public.pro_payable_bill_history;
create trigger pro_payable_bill_history_immutable before update on public.pro_payable_bill_history for each row execute function public.pro_payable_immutable();
drop trigger if exists pro_payable_action_immutable on public.pro_payable_actions;
create trigger pro_payable_action_immutable before update on public.pro_payable_actions for each row execute function public.pro_payable_immutable();

create or replace function public.pro_payable_today() returns date
language sql stable security invoker set search_path=public,pg_temp as $$ select (clock_timestamp() at time zone 'America/Costa_Rica')::date $$;

create or replace function public.pro_payable_uuid(p_value jsonb) returns uuid
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin
 if jsonb_typeof(p_value) is distinct from 'string' or (p_value#>>'{}')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'Invalid identifier' using errcode='22023';end if;
 return (p_value#>>'{}')::uuid;
end $$;

create or replace function public.pro_payable_period_check(p_from date,p_to date) returns void
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin
 if (p_from is not null and p_from not between date '2000-01-01' and date '2100-12-31') or (p_to is not null and p_to not between date '2000-01-01' and date '2100-12-31')
  or (p_from is not null and p_to is not null and p_from>p_to) then raise exception 'Invalid report period' using errcode='22023';end if;
end $$;

-- Every payable of the owner (expenses + PO supplier bills), with the derived balance and status.
create or replace function public.pro_payable_rows(p_owner uuid,p_today date)
returns table(source_kind text,source_id uuid,supplier_key text,supplier_id uuid,supplier_name text,vendor_kind text,work_id text,work_title text,
 reference text,concept text,doc_date date,due_date date,amount_cents bigint,paid_cents bigint,balance_cents bigint,net_cents bigint,status text,overdue boolean,
 bill_number text,note text,void_reason text,bill_revision integer,source_revision bigint)
language sql stable security invoker set search_path=public,pg_temp as $$
 with ex as (
  select 'expense'::text k,e.id,e.supplier_id sid,e.supplier_name sname,a.work_id wid,''::text ref,e.concept con,e.expense_date doc,coalesce(e.due_date,e.expense_date) due,e.amount_cents amount,
   coalesce((select sum(case when p.kind='payment' then p.amount_cents else -p.amount_cents end) from public.pro_expense_payments p where p.user_id=e.user_id and p.expense_id=e.id),0)::bigint paid,
   case when eb.vat_rate_bps is null then e.amount_cents else round(e.amount_cents*10000.0/(10000+eb.vat_rate_bps))::bigint end net,
   b.bill_number bn,b.note bnote,b.void_reason vr,coalesce(b.revision,0) brev,b.voided_at is not null voided,
   coalesce((select s.revision from public.pro_expense_state s where s.user_id=e.user_id),0)::bigint srev
  from public.pro_internal_expenses e
  left join public.pro_payable_bills b on b.owner_id=e.user_id and b.expense_id=e.id
  left join public.pro_work_expense_assignments a on a.user_id=e.user_id and a.expense_id=e.id
  left join public.pro_expense_billing eb on eb.user_id=e.user_id and eb.expense_id=e.id
  where e.user_id=p_owner),
 po as (
  select 'purchase_order'::text k,o.id,o.supplier_id sid,o.supplier_name sname,o.work_id wid,'OC-'||lpad(o.number::text,4,'0') ref,o.title con,b.bill_date doc,coalesce(b.due_date,b.bill_date) due,
   f.total_cents amount,f.paid_cents paid,f.subtotal_cents net,
   b.bill_number bn,b.note bnote,b.void_reason vr,b.revision brev,(b.voided_at is not null or o.status='cancelled') voided,o.revision::bigint srev
  from public.pro_payable_bills b join public.pro_purchase_orders o on o.owner_id=b.owner_id and o.id=b.purchase_order_id
  cross join lateral public.pro_purchase_order_figures(o.owner_id,o.id) f
  where b.owner_id=p_owner and b.source_kind='purchase_order')
 select x.k,x.id,coalesce(x.sid::text,'name:'||lower(btrim(x.sname))),x.sid,x.sname,coalesce(vp.kind,'supplier'),x.wid,coalesce(w.service,''),x.ref,x.con,x.doc,x.due,
  x.amount,x.paid,x.amount-x.paid,x.net,
  case when x.voided then 'void' when x.amount-x.paid<=0 then 'paid' when x.paid>0 then 'partial' else 'pending' end,
  not x.voided and x.amount-x.paid>0 and x.due<p_today,x.bn,x.bnote,x.vr,x.brev,x.srev
 from (select * from ex union all select * from po) x
 left join public.pro_company_vendor_profiles vp on vp.owner_id=p_owner and vp.supplier_id=x.sid
 left join public.pro_work w on w.user_id=p_owner and w.id=x.wid
$$;

create or replace function public.pro_payable_json(r record,p_today date) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 return jsonb_build_object('sourceKind',r.source_kind,'sourceId',r.source_id,'supplierKey',r.supplier_key,'supplierId',r.supplier_id,'supplierName',r.supplier_name,'vendorKind',r.vendor_kind,
  'workId',r.work_id,'workTitle',r.work_title,'reference',r.reference,'concept',r.concept,'docDate',to_char(r.doc_date,'YYYY-MM-DD'),'dueDate',to_char(r.due_date,'YYYY-MM-DD'),
  'amountCents',r.amount_cents,'paidCents',r.paid_cents,'balanceCents',greatest(r.balance_cents,0),'status',r.status,'overdue',r.overdue,
  'daysOverdue',case when r.overdue then p_today-r.due_date else 0 end,'billNumber',r.bill_number,'note',r.note,'voidReason',r.void_reason,
  'billRevision',r.bill_revision,'sourceRevision',r.source_revision);
end $$;

-- Accounts payable: list (filters), aging by supplier, totals and the issued orders still without a bill.
create or replace function public.pro_payables_read(p_actor uuid,p_query jsonb) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today date:=public.pro_payable_today();v_from date;v_to date;v_status text;v_supplier text;v_overdue boolean;items jsonb;suppliers jsonb;totals jsonb;aging jsonb;pending jsonb;matched integer;
begin
 if p_actor is null then raise exception 'Invalid actor' using errcode='22023';end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_query) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_query) k where k not in('from','to','status','supplier','overdue'))
  or exists(select 1 from jsonb_each(p_query) e where jsonb_typeof(e.value)<>'string') then raise exception 'Invalid query' using errcode='22023';end if;
 v_from:=public.pro_purchase_order_day(p_query->'from',false);v_to:=public.pro_purchase_order_day(p_query->'to',false);perform public.pro_payable_period_check(v_from,v_to);
 v_status:=coalesce(p_query->>'status','open');v_supplier:=nullif(p_query->>'supplier','');
 if v_status not in('open','all','paid','void') or coalesce(p_query->>'overdue','0') not in('0','1') or length(coalesce(v_supplier,''))>200 then raise exception 'Invalid query' using errcode='22023';end if;
 v_overdue:=coalesce(p_query->>'overdue','0')='1';
 with r as (select * from public.pro_payable_rows(p_actor,today) x where (v_from is null or x.doc_date>=v_from) and (v_to is null or x.doc_date<=v_to)),
 o as (select * from r where status in('pending','partial')),
 g as (select o.supplier_key,max(o.supplier_name) sname,(array_agg(o.supplier_id))[1] sid,max(o.vendor_kind) vkind,sum(o.balance_cents)::bigint open_cents,
   coalesce(sum(o.balance_cents) filter(where today-o.doc_date<=30),0)::bigint d0,coalesce(sum(o.balance_cents) filter(where today-o.doc_date between 31 and 60),0)::bigint d31,
   coalesce(sum(o.balance_cents) filter(where today-o.doc_date between 61 and 90),0)::bigint d61,coalesce(sum(o.balance_cents) filter(where today-o.doc_date>90),0)::bigint d90,
   coalesce(sum(o.balance_cents) filter(where o.overdue),0)::bigint overdue_cents,count(*)::integer n,max(today-o.doc_date) oldest
  from o group by o.supplier_key)
 select coalesce((select jsonb_agg(jsonb_build_object('supplierKey',g.supplier_key,'supplierId',g.sid,'supplierName',g.sname,'vendorKind',g.vkind,'openCents',g.open_cents,
   'd0_30',g.d0,'d31_60',g.d31,'d61_90',g.d61,'d90_plus',g.d90,'overdueCents',g.overdue_cents,'openBills',g.n,'oldestDays',g.oldest) order by g.open_cents desc,lower(g.sname),g.supplier_key) from g),'[]'::jsonb),
  jsonb_build_object('openCents',coalesce((select sum(balance_cents) from o),0)::bigint,'openCount',(select count(*) from o)::integer,
   'overdueCents',coalesce((select sum(balance_cents) from o where overdue),0)::bigint,'overdueCount',(select count(*) from o where overdue)::integer,
   'billedCents',coalesce((select sum(amount_cents) from r where status<>'void'),0)::bigint,'paidCents',coalesce((select sum(paid_cents) from r where status<>'void'),0)::bigint),
  jsonb_build_object('d0_30',coalesce((select sum(balance_cents) from o where today-doc_date<=30),0)::bigint,'d31_60',coalesce((select sum(balance_cents) from o where today-doc_date between 31 and 60),0)::bigint,
   'd61_90',coalesce((select sum(balance_cents) from o where today-doc_date between 61 and 90),0)::bigint,'d90_plus',coalesce((select sum(balance_cents) from o where today-doc_date>90),0)::bigint),
  (select count(*) from r where (v_status='all' or (v_status='open' and status in('pending','partial')) or status=v_status) and (v_supplier is null or supplier_key=v_supplier) and (not v_overdue or overdue))::integer,
  coalesce((select jsonb_agg(public.pro_payable_json(t,today) order by t.due_date,t.reference,t.source_id) from (select * from r where (v_status='all' or (v_status='open' and status in('pending','partial')) or status=v_status)
   and (v_supplier is null or supplier_key=v_supplier) and (not v_overdue or overdue) order by due_date,reference,source_id limit 200) t),'[]'::jsonb)
 into suppliers,totals,aging,matched,items;
 select coalesce(jsonb_agg(jsonb_build_object('purchaseOrderId',o.id,'workId',o.work_id,'workTitle',coalesce(w.service,''),'reference','OC-'||lpad(o.number::text,4,'0'),'title',o.title,
   'supplierName',o.supplier_name,'issueDate',to_char(o.issue_date,'YYYY-MM-DD'),'status',o.status,'totalCents',f.total_cents,'paidCents',f.paid_cents) order by o.issue_date,o.number),'[]'::jsonb) into pending
 from (select * from public.pro_purchase_orders x where x.owner_id=p_actor and x.status in('issued','partial','received')
   and not exists(select 1 from public.pro_payable_bills b where b.owner_id=x.owner_id and b.purchase_order_id=x.id) order by x.issue_date,x.number limit 50) o
 cross join lateral public.pro_purchase_order_figures(o.owner_id,o.id) f left join public.pro_work w on w.user_id=o.owner_id and w.id=o.work_id;
 return jsonb_build_object('today',to_char(today,'YYYY-MM-DD'),'from',to_char(v_from,'YYYY-MM-DD'),'to',to_char(v_to,'YYYY-MM-DD'),'status',v_status,'supplier',v_supplier,'overdue',v_overdue,
  'totals',totals,'aging',aging,'suppliers',suppliers,'items',items,'matched',matched,'truncated',matched>200,'toRegister',pending);
end $$;

-- Bill record (save / void / restore) and payments made through the existing writers.
create or replace function public.pro_payables_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;v_kind text;sid uuid;rev integer;keys text[];expected text[];receipt public.pro_payable_actions;b public.pro_payable_bills;o public.pro_purchase_orders;e public.pro_internal_expenses;
 before_json jsonb;after_json jsonb;result jsonb;v_number text;v_bill date;v_due date;v_note text;v_reason text;today date:=public.pro_payable_today();cur record;v_amount numeric;v_paid_on date;v_method text;v_ref text;v_srev numeric;
begin
 if p_actor is null or not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid payable' using errcode='22023';end if;
 act:=p_input->>'action';
 expected:=case act
  when 'save' then array['action','actionId','billDate','billNumber','dueDate','note','revision','sourceId','sourceKind']
  when 'void' then array['action','actionId','reason','revision','sourceId','sourceKind']
  when 'restore' then array['action','actionId','revision','sourceId','sourceKind']
  when 'pay' then array['action','actionId','amountCents','method','note','paidOn','reference','revision','sourceId','sourceKind','sourceRevision'] end;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if expected is null or keys is distinct from expected then raise exception 'Invalid payable fields' using errcode='22023';end if;
 aid:=public.pro_payable_uuid(p_input->'actionId');sid:=public.pro_payable_uuid(p_input->'sourceId');v_kind:=p_input->>'sourceKind';
 if jsonb_typeof(p_input->'sourceKind') is distinct from 'string' or v_kind not in('purchase_order','expense') then raise exception 'Invalid source' using errcode='22023';end if;
 if jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 rev:=(p_input->>'revision')::integer;
 -- Shape validation without state (22023).
 if act='save' then
  v_number:=public.pro_purchase_order_text(p_input->'billNumber',60,false);v_note:=public.pro_purchase_order_text(p_input->'note',300,false);
  v_bill:=public.pro_purchase_order_day(p_input->'billDate',false);v_due:=public.pro_purchase_order_day(p_input->'dueDate',false);
  if v_kind='expense' and (v_bill is not null or v_due is not null) then raise exception 'The due date of an expense is edited in Expenses' using errcode='22023';end if;
  if v_kind='purchase_order' and v_bill is null then raise exception 'Missing bill date' using errcode='22023';end if;
  if v_bill is not null and (v_bill not between date '2000-01-01' and today) then raise exception 'Invalid bill date' using errcode='22023';end if;
  if v_due is not null and (v_due<v_bill or v_due>date '2100-12-31') then raise exception 'Invalid due date' using errcode='22023';end if;
 elsif act='void' then
  v_reason:=public.pro_purchase_order_text(p_input->'reason',300,true);
 elsif act='pay' then
  if jsonb_typeof(p_input->'amountCents') is distinct from 'number' or jsonb_typeof(p_input->'method') is distinct from 'string' or jsonb_typeof(p_input->'sourceRevision') is distinct from 'number'
   or not coalesce((p_input->>'sourceRevision')~'^[0-9]{1,15}$',false) then raise exception 'Invalid payment' using errcode='22023';end if;
  v_amount:=(p_input->>'amountCents')::numeric;v_method:=p_input->>'method';v_srev:=(p_input->>'sourceRevision')::numeric;
  v_paid_on:=public.pro_purchase_order_day(p_input->'paidOn',true);
  v_ref:=public.pro_purchase_order_text(p_input->'reference',160,false);v_note:=public.pro_purchase_order_text(p_input->'note',300,false);
  if v_amount<>round(v_amount) or v_amount not between 1 and 10000000000 or v_paid_on>today or v_paid_on<date '2000-01-01'
   or (v_kind='expense' and v_method not in('cash','transfer','card','other')) or (v_kind='purchase_order' and v_method not in('transfer','sinpe','cash','card','check','other')) then raise exception 'Invalid payment values' using errcode='22023';end if;
 end if;
 -- Idempotent receipt by actionId.
 perform pg_advisory_xact_lock(hashtextextended('pro-payables-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_payable_actions where owner_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-payables:'||p_actor::text||':'||v_kind||':'||sid::text,0));
 if v_kind='purchase_order' then
  select * into o from public.pro_purchase_orders where owner_id=p_actor and id=sid for update;
  if not found then raise exception 'Unknown purchase order' using errcode='P0002';end if;
  select * into b from public.pro_payable_bills where owner_id=p_actor and purchase_order_id=sid for update;
 else
  select * into e from public.pro_internal_expenses where user_id=p_actor and id=sid for update;
  if not found then raise exception 'Unknown expense' using errcode='P0002';end if;
  select * into b from public.pro_payable_bills where owner_id=p_actor and expense_id=sid for update;
 end if;
 if coalesce(b.revision,0)<>rev then raise exception 'Payable changed' using errcode='40001';end if;
 select * into cur from public.pro_payable_rows(p_actor,today) x where x.source_kind=v_kind and x.source_id=sid;
 before_json:=case when b.id is null then null else to_jsonb(b)-'owner_id' end;
 if act='save' then
  if b.voided_at is not null then raise exception 'Restore the bill before editing it' using errcode='22023',hint='pro_payable_void';end if;
  if v_kind='purchase_order' then
   if o.status not in('issued','partial','received') then raise exception 'Issue the order before recording its bill' using errcode='22023',hint='pro_payable_order_state';end if;
   if v_bill<o.issue_date then raise exception 'Bill date before the order' using errcode='22023';end if;
  end if;
  if b.id is null then
   insert into public.pro_payable_bills(owner_id,source_kind,purchase_order_id,expense_id,bill_number,bill_date,due_date,note)
    values(p_actor,v_kind,case when v_kind='purchase_order' then sid end,case when v_kind='expense' then sid end,v_number,v_bill,v_due,v_note) returning * into b;
  else
   if b.bill_number is not distinct from v_number and b.bill_date is not distinct from v_bill and b.due_date is not distinct from v_due and b.note is not distinct from v_note then raise exception 'No changes' using errcode='22023';end if;
   update public.pro_payable_bills set bill_number=v_number,bill_date=v_bill,due_date=v_due,note=v_note,revision=revision+1,updated_at=now() where owner_id=p_actor and id=b.id returning * into b;
  end if;
 elsif act='void' then
  if b.voided_at is not null then raise exception 'Already voided' using errcode='22023';end if;
  if v_kind='purchase_order' and b.id is null then raise exception 'Record the bill first' using errcode='22023';end if;
  if cur.paid_cents>0 then raise exception 'Reverse the payments before voiding' using errcode='22023',hint='pro_payable_paid';end if;
  if b.id is null then
   insert into public.pro_payable_bills(owner_id,source_kind,expense_id,voided_at,void_reason) values(p_actor,'expense',sid,now(),v_reason) returning * into b;
  else
   update public.pro_payable_bills set voided_at=now(),void_reason=v_reason,revision=revision+1,updated_at=now() where owner_id=p_actor and id=b.id returning * into b;
  end if;
 elsif act='restore' then
  if b.voided_at is null then raise exception 'Not voided' using errcode='22023';end if;
  if v_kind='purchase_order' and o.status='cancelled' then raise exception 'Cancelled order' using errcode='22023',hint='pro_payable_order_state';end if;
  update public.pro_payable_bills set voided_at=null,void_reason=null,revision=revision+1,updated_at=now() where owner_id=p_actor and id=b.id returning * into b;
 else -- pay: validated here, written by the source module's own writer (same actionId, its own receipt and history).
  if v_kind='purchase_order' and b.id is null then raise exception 'Record the bill first' using errcode='22023';end if;
  if b.voided_at is not null or cur.status='void' then raise exception 'Voided bill' using errcode='22023',hint='pro_payable_void';end if;
  if v_amount>cur.balance_cents then raise exception 'Payment exceeds balance' using errcode='22023',hint='pro_payable_balance';end if;
  if v_kind='expense' then
   if v_paid_on<e.expense_date then raise exception 'Payment before the expense' using errcode='22023';end if;
   perform public.pro_expense_meta_save(p_actor,jsonb_build_object('action','payment','actionId',aid,'revision',v_srev,'expenseId',sid,'amountCents',v_amount,'date',to_char(v_paid_on,'YYYY-MM-DD'),
    'method',v_method,'reference',coalesce(v_ref,''),'note',coalesce(v_note,'')));
  else
   if v_paid_on<o.issue_date then raise exception 'Payment before the order' using errcode='22023';end if;
   perform public.pro_purchase_orders_mutate(p_actor,jsonb_build_object('action','pay','actionId',aid,'amountCents',v_amount,'id',sid,'method',v_method,'note',v_note,'paidOn',to_char(v_paid_on,'YYYY-MM-DD'),
    'reference',v_ref,'revision',v_srev,'workId',o.work_id));
  end if;
 end if;
 if act<>'pay' then
  after_json:=to_jsonb(b)-'owner_id';
  insert into public.pro_payable_bill_history(owner_id,bill_id,action_id,action,before_value,after_value) values(p_actor,b.id,aid,act,before_json,after_json);
 end if;
 select public.pro_payable_json(x,today) into result from public.pro_payable_rows(p_actor,today) x where x.source_kind=v_kind and x.source_id=sid;
 result:=jsonb_build_object('payable',result);
 insert into public.pro_payable_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Cash flow per week (ISO, Monday) or month of [p_from, p_to].
create or replace function public.pro_cash_flow_read(p_actor uuid,p_from date,p_to date,p_grain text default 'month') returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today date:=public.pro_payable_today();n integer;step interval;periods jsonb;totals jsonb;overdue jsonb;plan record;item jsonb;inst jsonb:='[]'::jsonb;undated bigint:=0;
begin
 if p_actor is null then raise exception 'Invalid actor' using errcode='22023';end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_from is null or p_to is null then raise exception 'Invalid report period' using errcode='22023';end if;
 perform public.pro_payable_period_check(p_from,p_to);
 if p_grain is null or p_grain not in('week','month') then raise exception 'Invalid grain' using errcode='22023';end if;
 if p_grain='week' then step:=interval '7 days';n:=(date_trunc('week',p_to)::date-date_trunc('week',p_from)::date)/7+1;
 else step:=interval '1 month';n:=(extract(year from p_to)::integer*12+extract(month from p_to)::integer)-(extract(year from p_from)::integer*12+extract(month from p_from)::integer)+1;end if;
 if (p_grain='week' and n>106) or (p_grain='month' and n>60) then raise exception 'Period too long' using errcode='22023';end if;
 -- Open installments of active payment plans (their own derived state).
 for plan in select p.id,p.work_id from public.pro_payment_plans p where p.owner_id=p_actor and p.status='active' order by p.created_at limit 200 loop
  for item in select value from jsonb_array_elements(coalesce(public.pro_payment_plan_state(p_actor,plan.id,today)->'items','[]'::jsonb)) loop
   if item->>'status'<>'paid' and coalesce((item->>'amountCents')::bigint,0)-coalesce((item->>'appliedCents')::bigint,0)>0 then
    if item->>'dueDate' is null then undated:=undated+(item->>'amountCents')::bigint-coalesce((item->>'appliedCents')::bigint,0);
    else inst:=inst||jsonb_build_array(jsonb_build_object('planId',plan.id,'workId',plan.work_id,'seq',(item->>'seq')::integer,'kind',item->>'kind','due',item->>'dueDate',
     'amount',(item->>'amountCents')::bigint-coalesce((item->>'appliedCents')::bigint,0)));end if;
   end if;
  end loop;
 end loop;
 with ev as (
  -- In, actual: payments received (reversed ones left out).
  select 'in'::text dir,true actual,'payment'::text kind,p.id::text id,p.received_on due,p.amount_cents::bigint amount,coalesce(c.name,'') party,coalesce(w.service,'') work,coalesce(p.reference,'') label
   from public.pro_invoice_payments p left join public.pro_clients c on c.user_id=p.user_id and c.id=p.client_id left join public.pro_work w on w.user_id=p.user_id and w.id=p.work_id
   where p.user_id=p_actor and p.received_on between p_from and p_to and not public.pro_credit_entry_reversed(p_actor,p.entry_id)
  union all -- Out, actual: refunds to customers (not voided).
  select 'out',true,'refund',r.id::text,r.refunded_on,r.amount_cents,'','',''
   from public.pro_credit_refunds r where r.owner_id=p_actor and r.refunded_on between p_from and p_to and not exists(select 1 from public.pro_credit_refund_voids v where v.owner_id=r.owner_id and v.refund_id=r.id)
  union all -- Out, actual: expense payments (a reversal is negative on its own day).
  select 'out',true,'expense_payment',p.id::text,p.paid_on,case when p.kind='payment' then p.amount_cents else -p.amount_cents end,x.supplier_name,'',x.concept
   from public.pro_expense_payments p join public.pro_internal_expenses x on x.user_id=p.user_id and x.id=p.expense_id where p.user_id=p_actor and p.paid_on between p_from and p_to
  union all -- Out, actual: purchase-order payments.
  select 'out',true,'po_payment',p.id::text,p.paid_on,case when p.kind='payment' then p.amount_cents else -p.amount_cents end,o.supplier_name,'','OC-'||lpad(o.number::text,4,'0')
   from public.pro_purchase_order_payments p join public.pro_purchase_orders o on o.owner_id=p.owner_id and o.id=p.order_id where p.owner_id=p_actor and p.paid_on between p_from and p_to
  union all -- In, expected: open invoice drafts (installment drafts are counted by their installment).
  select 'in',false,'invoice',d.id::text,coalesce(pp.planned_date,(d.created_at at time zone 'America/Costa_Rica')::date)+case when pp.sale_condition='credit' then pp.credit_days else 0 end,
   public.pro_report_draft_open(p_actor,d.id),coalesce(c.name,d.receiver_name),coalesce(w.service,''),d.title
   from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
   left join public.pro_invoice_preparation pp on pp.user_id=d.user_id and pp.draft_id=d.id
   left join public.pro_clients c on c.user_id=d.user_id and c.id=d.client_id left join public.pro_work w on w.user_id=d.user_id and w.id=d.work_id
   where d.user_id=p_actor and not coalesce(m.archived,false)
    and not exists(select 1 from public.pro_invoice_billing_items i where i.user_id=d.user_id and i.draft_id=d.id and i.active and i.source_type='installment')
  union all -- In, expected: open payment-plan installments with a known date.
  select 'in',false,'installment',(j->>'planId')||':'||(j->>'seq'),(j->>'due')::date,(j->>'amount')::bigint,coalesce(w.client,''),coalesce(w.service,''),(j->>'seq')
   from jsonb_array_elements(inst) j left join public.pro_work w on w.user_id=p_actor and w.id=j->>'workId'
  union all -- Out, expected: open payables.
  select 'out',false,x.source_kind,x.source_id::text,x.due_date,x.balance_cents,x.supplier_name,x.work_title,case when x.source_kind='purchase_order' then x.reference else x.concept end
   from public.pro_payable_rows(p_actor,today) x where x.status in('pending','partial')),
 placed as (select ev.*,case when actual then due else greatest(due,today) end at_day,(not actual and due<today) is_overdue from ev where amount<>0),
 ps as (select g::date start,(g+step-interval '1 day')::date finish from generate_series(case when p_grain='week' then date_trunc('week',p_from) else date_trunc('month',p_from) end,
   case when p_grain='week' then date_trunc('week',p_to) else date_trunc('month',p_to) end,step) g),
 per as (select ps.start,ps.finish,
   coalesce(sum(pl.amount) filter(where pl.dir='in' and pl.actual),0)::bigint ain,coalesce(sum(pl.amount) filter(where pl.dir='out' and pl.actual),0)::bigint aout,
   coalesce(sum(pl.amount) filter(where pl.dir='in' and not pl.actual),0)::bigint ein,coalesce(sum(pl.amount) filter(where pl.dir='out' and not pl.actual),0)::bigint eout,
   coalesce(sum(pl.amount) filter(where pl.dir='in' and pl.is_overdue),0)::bigint oin,coalesce(sum(pl.amount) filter(where pl.dir='out' and pl.is_overdue),0)::bigint oout
  from ps left join placed pl on pl.at_day between greatest(ps.start,p_from) and least(ps.finish,p_to) group by ps.start,ps.finish),
 run as (select per.*,sum(ain-aout+ein-eout) over(order by start) cumulative from per)
 select coalesce(jsonb_agg(jsonb_build_object('start',to_char(greatest(start,p_from),'YYYY-MM-DD'),'end',to_char(least(finish,p_to),'YYYY-MM-DD'),'current',today between start and finish,
   'actualInCents',ain,'actualOutCents',aout,'expectedInCents',ein,'expectedOutCents',eout,'overdueInCents',oin,'overdueOutCents',oout,
   'netCents',ain-aout+ein-eout,'cumulativeCents',cumulative::bigint) order by start),'[]'::jsonb),
  jsonb_build_object('actualInCents',coalesce(sum(ain),0)::bigint,'actualOutCents',coalesce(sum(aout),0)::bigint,'expectedInCents',coalesce(sum(ein),0)::bigint,'expectedOutCents',coalesce(sum(eout),0)::bigint,
   'netCents',coalesce(sum(ain-aout+ein-eout),0)::bigint)
 into periods,totals from run;
 -- Overdue as of today (whole account, not only the window): what should already have come in or gone out.
 with od as (
  select 'in'::text dir,'invoice'::text kind,d.id::text id,coalesce(c.name,d.receiver_name) party,coalesce(w.service,'') work,d.title label,
   coalesce(pp.planned_date,(d.created_at at time zone 'America/Costa_Rica')::date)+case when pp.sale_condition='credit' then pp.credit_days else 0 end due,public.pro_report_draft_open(p_actor,d.id) amount
   from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
   left join public.pro_invoice_preparation pp on pp.user_id=d.user_id and pp.draft_id=d.id
   left join public.pro_clients c on c.user_id=d.user_id and c.id=d.client_id left join public.pro_work w on w.user_id=d.user_id and w.id=d.work_id
   where d.user_id=p_actor and not coalesce(m.archived,false)
    and not exists(select 1 from public.pro_invoice_billing_items i where i.user_id=d.user_id and i.draft_id=d.id and i.active and i.source_type='installment')
  union all
  select 'in','installment',(j->>'planId')||':'||(j->>'seq'),coalesce(w.client,''),coalesce(w.service,''),(j->>'seq'),(j->>'due')::date,(j->>'amount')::bigint
   from jsonb_array_elements(inst) j left join public.pro_work w on w.user_id=p_actor and w.id=j->>'workId'
  union all
  select 'out',x.source_kind,x.source_id::text,x.supplier_name,x.work_title,case when x.source_kind='purchase_order' then x.reference else x.concept end,x.due_date,x.balance_cents
   from public.pro_payable_rows(p_actor,today) x where x.status in('pending','partial'))
 select jsonb_build_object('inCents',coalesce(sum(amount) filter(where dir='in'),0)::bigint,'outCents',coalesce(sum(amount) filter(where dir='out'),0)::bigint,'count',count(*)::integer,
  'items',coalesce((select jsonb_agg(jsonb_build_object('direction',t.dir,'kind',t.kind,'id',t.id,'party',t.party,'workTitle',t.work,'label',t.label,'dueDate',to_char(t.due,'YYYY-MM-DD'),
   'amountCents',t.amount,'daysOverdue',today-t.due) order by t.due,t.dir,t.id) from (select * from od where amount>0 and due<today order by due,dir,id limit 100) t),'[]'::jsonb))
 into overdue from od where amount>0 and due<today;
 return jsonb_build_object('today',to_char(today,'YYYY-MM-DD'),'from',to_char(p_from,'YYYY-MM-DD'),'to',to_char(p_to,'YYYY-MM-DD'),'grain',p_grain,
  'periods',periods,'totals',totals||jsonb_build_object('undatedInCents',undated),'overdue',overdue);
end $$;

-- Simple income statement (management report, not a tax filing) per period and per job.
create or replace function public.pro_income_statement_read(p_actor uuid,p_from date,p_to date,p_grain text default 'month') returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today date:=public.pro_payable_today();n integer;step interval;periods jsonb;totals jsonb;jobs jsonb;categories jsonb;tax_unknown integer;job_count integer;
begin
 if p_actor is null then raise exception 'Invalid actor' using errcode='22023';end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_from is null or p_to is null then raise exception 'Invalid report period' using errcode='22023';end if;
 perform public.pro_payable_period_check(p_from,p_to);
 if p_grain is null or p_grain not in('month','quarter','year') then raise exception 'Invalid grain' using errcode='22023';end if;
 step:=case p_grain when 'month' then interval '1 month' when 'quarter' then interval '3 months' else interval '1 year' end;
 n:=case p_grain when 'year' then extract(year from p_to)::integer-extract(year from p_from)::integer+1
  else ((extract(year from p_to)::integer*12+extract(month from p_to)::integer)-(extract(year from p_from)::integer*12+extract(month from p_from)::integer))/case when p_grain='quarter' then 3 else 1 end+1 end;
 if n>60 then raise exception 'Period too long' using errcode='22023';end if;
 with l as (
  -- Income: invoice drafts without IVA (not archived), by creation day in Costa Rica.
  select 'income'::text side,'invoiced'::text line,(d.created_at at time zone 'America/Costa_Rica')::date on_day,d.work_id,(d.total_cents-coalesce(d.tax_cents,0))::bigint amount,(d.tax_cents is null) unknown
   from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
   where d.user_id=p_actor and not coalesce(m.archived,false)
  union all -- Collected (cash basis, informational; not in the result).
  select 'info','collected',p.received_on,p.work_id,p.amount_cents::bigint,false from public.pro_invoice_payments p
   where p.user_id=p_actor and not public.pro_credit_entry_reversed(p_actor,p.entry_id)
  union all -- Costs: expenses without IVA when the rate is known, per category (voided ones left out).
  select 'cost','expense:'||coalesce(eb.category,'uncategorized'),e.expense_date,a.work_id,
   case when eb.vat_rate_bps is null then e.amount_cents else round(e.amount_cents*10000.0/(10000+eb.vat_rate_bps))::bigint end,false
   from public.pro_internal_expenses e left join public.pro_expense_billing eb on eb.user_id=e.user_id and eb.expense_id=e.id
   left join public.pro_work_expense_assignments a on a.user_id=e.user_id and a.expense_id=e.id
   where e.user_id=p_actor and not exists(select 1 from public.pro_payable_bills b where b.owner_id=e.user_id and b.expense_id=e.id and b.voided_at is not null)
  union all -- Costs: internal cost of recorded hours (a void is negative on its own day).
  select 'cost','labor',c.recorded_on,c.work_id,case when c.kind='time' then c.amount_cents else -c.amount_cents end,false
   from public.pro_work_cost_entries c where c.user_id=p_actor and c.kind in('time','time_void') and c.amount_cents is not null
  union all -- Costs: supplier bills of purchase orders without tax (bill date).
  select 'cost','purchase_bills',b.bill_date,o.work_id,f.subtotal_cents,false
   from public.pro_payable_bills b join public.pro_purchase_orders o on o.owner_id=b.owner_id and o.id=b.purchase_order_id
   cross join lateral public.pro_purchase_order_figures(o.owner_id,o.id) f
   where b.owner_id=p_actor and b.voided_at is null and o.status<>'cancelled'),
 w as (select * from l where on_day between p_from and p_to),
 ps as (select g::date start,(g+step-interval '1 day')::date finish from generate_series(
   case p_grain when 'month' then date_trunc('month',p_from) when 'quarter' then date_trunc('quarter',p_from) else date_trunc('year',p_from) end,
   case p_grain when 'month' then date_trunc('month',p_to) when 'quarter' then date_trunc('quarter',p_to) else date_trunc('year',p_to) end,step) g),
 per as (select ps.start,ps.finish,
   coalesce(sum(w.amount) filter(where w.side='income'),0)::bigint income,coalesce(sum(w.amount) filter(where w.line='collected'),0)::bigint collected,
   coalesce(sum(w.amount) filter(where w.line like 'expense:%'),0)::bigint expenses,coalesce(sum(w.amount) filter(where w.line='labor'),0)::bigint labor,
   coalesce(sum(w.amount) filter(where w.line='purchase_bills'),0)::bigint bills
  from ps left join w on w.on_day between ps.start and ps.finish group by ps.start,ps.finish)
 select coalesce(jsonb_agg(jsonb_build_object('start',to_char(greatest(start,p_from),'YYYY-MM-DD'),'end',to_char(least(finish,p_to),'YYYY-MM-DD'),
   'incomeCents',income,'collectedCents',collected,'expensesCents',expenses,'laborCents',labor,'purchaseBillsCents',bills,'costCents',expenses+labor+bills,'resultCents',income-expenses-labor-bills) order by start),'[]'::jsonb),
  jsonb_build_object('incomeCents',coalesce(sum(income),0)::bigint,'collectedCents',coalesce(sum(collected),0)::bigint,'expensesCents',coalesce(sum(expenses),0)::bigint,'laborCents',coalesce(sum(labor),0)::bigint,
   'purchaseBillsCents',coalesce(sum(bills),0)::bigint,'costCents',coalesce(sum(expenses+labor+bills),0)::bigint,'resultCents',coalesce(sum(income-expenses-labor-bills),0)::bigint)
 into periods,totals from per;
 with l as (
  select (d.created_at at time zone 'America/Costa_Rica')::date on_day,d.tax_cents is null unknown from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
  where d.user_id=p_actor and not coalesce(m.archived,false))
 select count(*) filter(where unknown)::integer into tax_unknown from l where on_day between p_from and p_to;
 -- Expense categories of the period.
 select coalesce(jsonb_agg(jsonb_build_object('category',k,'cents',s) order by s desc,k),'[]'::jsonb) into categories from (
  select coalesce(eb.category,'uncategorized') k,sum(case when eb.vat_rate_bps is null then e.amount_cents else round(e.amount_cents*10000.0/(10000+eb.vat_rate_bps))::bigint end)::bigint s
  from public.pro_internal_expenses e left join public.pro_expense_billing eb on eb.user_id=e.user_id and eb.expense_id=e.id
  where e.user_id=p_actor and e.expense_date between p_from and p_to and not exists(select 1 from public.pro_payable_bills b where b.owner_id=e.user_id and b.expense_id=e.id and b.voided_at is not null)
  group by 1) c;
 -- Per job (and the costs/income without a job), same lines as above.
 with l as (
  select 'income'::text line,d.work_id,(d.total_cents-coalesce(d.tax_cents,0))::bigint amount from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
   where d.user_id=p_actor and not coalesce(m.archived,false) and (d.created_at at time zone 'America/Costa_Rica')::date between p_from and p_to
  union all select 'collected',p.work_id,p.amount_cents::bigint from public.pro_invoice_payments p where p.user_id=p_actor and p.received_on between p_from and p_to and not public.pro_credit_entry_reversed(p_actor,p.entry_id)
  union all select 'expenses',a.work_id,case when eb.vat_rate_bps is null then e.amount_cents else round(e.amount_cents*10000.0/(10000+eb.vat_rate_bps))::bigint end
   from public.pro_internal_expenses e left join public.pro_expense_billing eb on eb.user_id=e.user_id and eb.expense_id=e.id left join public.pro_work_expense_assignments a on a.user_id=e.user_id and a.expense_id=e.id
   where e.user_id=p_actor and e.expense_date between p_from and p_to and not exists(select 1 from public.pro_payable_bills b where b.owner_id=e.user_id and b.expense_id=e.id and b.voided_at is not null)
  union all select 'labor',c.work_id,case when c.kind='time' then c.amount_cents else -c.amount_cents end from public.pro_work_cost_entries c
   where c.user_id=p_actor and c.kind in('time','time_void') and c.amount_cents is not null and c.recorded_on between p_from and p_to
  union all select 'bills',o.work_id,f.subtotal_cents from public.pro_payable_bills b join public.pro_purchase_orders o on o.owner_id=b.owner_id and o.id=b.purchase_order_id
   cross join lateral public.pro_purchase_order_figures(o.owner_id,o.id) f where b.owner_id=p_actor and b.voided_at is null and o.status<>'cancelled' and b.bill_date between p_from and p_to),
 g as (select l.work_id,coalesce(sum(amount) filter(where line='income'),0)::bigint income,coalesce(sum(amount) filter(where line='collected'),0)::bigint collected,
   coalesce(sum(amount) filter(where line='expenses'),0)::bigint expenses,coalesce(sum(amount) filter(where line='labor'),0)::bigint labor,coalesce(sum(amount) filter(where line='bills'),0)::bigint bills
  from l group by l.work_id),
 r as (select g.*,income-expenses-labor-bills result from g)
 select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object('workId',r.work_id,'service',coalesce(wk.service,''),'client',coalesce(wk.client,''),'incomeCents',r.income,'collectedCents',r.collected,
   'expensesCents',r.expenses,'laborCents',r.labor,'purchaseBillsCents',r.bills,'costCents',r.expenses+r.labor+r.bills,'resultCents',r.result) order by r.work_id is null,r.result desc,coalesce(wk.service,''),r.work_id) filter(where r.rn<=200),'[]'::jsonb)
 into job_count,jobs from (select r.*,row_number() over(order by r.work_id is null,r.result desc,r.work_id) rn from r) r left join public.pro_work wk on wk.user_id=p_actor and wk.id=r.work_id;
 return jsonb_build_object('today',to_char(today,'YYYY-MM-DD'),'from',to_char(p_from,'YYYY-MM-DD'),'to',to_char(p_to,'YYYY-MM-DD'),'grain',p_grain,'basis','management',
  'periods',periods,'totals',totals,'categories',categories,'jobs',jobs,'jobsTruncated',job_count>200,'taxUnknownInvoices',tax_unknown);
end $$;

-- ---------------------------------------------------------------- RLS and grants (service_role only)
do $$declare t text;begin foreach t in array array['pro_payable_bills','pro_payable_bill_history','pro_payable_actions'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);
 execute format('grant select,insert,update,delete on public.%I to service_role',t);
end loop;end $$;
revoke update,delete,truncate on public.pro_payable_bill_history,public.pro_payable_actions from service_role;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
  and p.proname in('pro_payable_immutable','pro_payable_today','pro_payable_uuid','pro_payable_period_check','pro_payable_rows','pro_payable_json','pro_payables_read','pro_payables_mutate','pro_cash_flow_read','pro_income_statement_read') loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_payable_immutable(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;
